/*
 * Event Timeline — таймлайн событий для Obsidian.
 *
 * Сборщик не нужен: main.js — маленький загрузчик, который читает модули
 * из папки src/ через API хранилища и исполняет их как CommonJS-модули.
 * Работает и на десктопе, и на мобильных (node не используется).
 *
 * Если папки src/ рядом нет (например, установщик скопировал только
 * main.js, manifest.json и styles.css), используется встроенная копия
 * модулей из конца этого файла. Папка src/ всегда в приоритете — правки
 * в ней подхватываются без пересборки.
 */
'use strict';

const obsidian = require('obsidian');

/** Мини-реализация CommonJS поверх файлов плагина. */
class ModuleLoader {
  constructor(plugin) {
    this.plugin = plugin;
    this.root = null;
    this.sources = new Map(); // id -> текст модуля
    this.cache = new Map();   // id -> module
  }

  /** Папка плагина: manifest.dir, а если его нет — <configDir>/plugins/<id>. */
  pluginDir() {
    const { manifest, app } = this.plugin;
    return obsidian.normalizePath(manifest.dir || `${app.vault.configDir}/plugins/${manifest.id}`);
  }

  /** Ищет src/ рядом с main.js, а также на уровень глубже (если архив распаковался во вложенную папку). */
  async findRoot() {
    const adapter = this.plugin.app.vault.adapter;
    const dir = this.pluginDir();
    const candidates = [`${dir}/src`, `${dir}/${this.plugin.manifest.id}/src`];
    try {
      const listing = await adapter.list(dir);
      for (const folder of listing.folders) candidates.push(`${folder}/src`);
    } catch (e) { /* папка не читается — сообщим ниже */ }
    for (const c of candidates) {
      const path = obsidian.normalizePath(c);
      if ((await adapter.exists(path)) && (await adapter.exists(`${path}/plugin.js`))) return path;
    }
    let content = '';
    try {
      const listing = await adapter.list(dir);
      content = [...listing.folders, ...listing.files].map((p) => p.split('/').pop()).join(', ');
    } catch (e) { content = 'не удалось прочитать'; }
    throw new Error(
      `не найдена папка модулей ${dir}/src (с файлом plugin.js). ` +
      `Скопируйте в папку плагина всю папку src из архива. Сейчас в ${dir}: ${content || 'пусто'}`);
  }

  async init() {
    const adapter = this.plugin.app.vault.adapter;
    try {
      this.root = await this.findRoot();
    } catch (err) {
      if (!BUNDLED_SOURCES) throw err;
      for (const [id, code] of Object.entries(BUNDLED_SOURCES)) this.sources.set(id, code);
      this.root = 'встроенная копия';
      console.warn(`[Event Timeline] папка src не найдена, используется встроенная копия модулей (${this.sources.size}). ${err.message}`);
      return;
    }
    const walk = async (dir) => {
      const listing = await adapter.list(dir);
      for (const file of listing.files) {
        if (!file.endsWith('.js')) continue;
        const id = file.slice(this.root.length + 1, -3);
        this.sources.set(id, await adapter.read(file));
      }
      for (const folder of listing.folders) await walk(folder);
    };
    await walk(this.root);
    console.log(`[Event Timeline] загружено модулей: ${this.sources.size} из ${this.root}`);
  }

  resolve(fromId, request) {
    const base = fromId.split('/').slice(0, -1);
    const parts = request.replace(/\.js$/, '').split('/');
    for (const part of parts) {
      if (part === '.' || part === '') continue;
      if (part === '..') base.pop();
      else base.push(part);
    }
    return base.join('/');
  }

  require(request, fromId = 'main') {
    if (request === 'obsidian') return obsidian;
    if (!request.startsWith('.')) return require(request);
    const id = this.resolve(fromId, request);
    if (this.cache.has(id)) return this.cache.get(id).exports;
    const source = this.sources.get(id);
    if (source == null) throw new Error(`Модуль не найден: src/${id}.js (запрошен из ${fromId})`);
    const module = { id, exports: {} };
    this.cache.set(id, module);
    const localRequire = (req) => this.require(req, id);
    const fn = new Function('require', 'module', 'exports',
      `${source}\n//# sourceURL=event-timeline/src/${id}.js`);
    fn(localRequire, module, module.exports);
    return module.exports;
  }
}

module.exports = class EventTimelinePlugin extends obsidian.Plugin {
  async onload() {
    try {
      this.modules = new ModuleLoader(this);
      await this.modules.init();
      const { bootstrap } = this.modules.require('./plugin');
      await bootstrap(this);
    } catch (err) {
      console.error('[Event Timeline] ошибка загрузки', err);
      new obsidian.Notice(`Event Timeline: ошибка загрузки — ${err.message}`, 20000);
    }
  }

  onunload() {
    if (this.teardown) this.teardown();
  }
};

/* Встроенная копия src/ — генерируется при выпуске версии, вручную не править. */
const BUNDLED_SOURCES = {"constants":"'use strict';\n\n/** Основной язык блока и устаревший (Timeline Card v2) — оба рендерятся одинаково. */\nconst BLOCK_LANGUAGE = 'timeline';\nconst LEGACY_LANGUAGE = 'track';\nconst BLOCK_LANGUAGES = [BLOCK_LANGUAGE, LEGACY_LANGUAGE];\nconst PROPS_VIEW_TYPE = 'event-timeline-properties';\nconst HOVER_SOURCE = 'event-timeline';\n\n/** Типы буллетов (маркеров на линии времени). */\nconst MARKERS = {\n  done:    { key: 'done',    label: 'Готово',   legend: 'Выполнено',  icon: 'check' },\n  warning: { key: 'warning', label: 'Внимание', legend: 'Тревога',    icon: 'alert-triangle' },\n  info:    { key: 'info',    label: 'Инфо',     legend: 'Инфо',       icon: 'clock-3' },\n  accent:  { key: 'accent',  label: 'Акцент',   legend: 'Акцент',     icon: null },\n  empty:   { key: 'empty',   label: 'Пустой',   legend: 'Без статуса', icon: null },\n};\nconst MARKER_ORDER = ['done', 'warning', 'info', 'accent', 'empty'];\n\n/** Синонимы, которые понимает парсер в поле marker:: */\nconst MARKER_ALIASES = {\n  done: 'done', ok: 'done', check: 'done', готово: 'done', выполнено: 'done', завершено: 'done',\n  warning: 'warning', warn: 'warning', alert: 'warning', внимание: 'warning', тревога: 'warning',\n  info: 'info', инфо: 'info', информация: 'info',\n  accent: 'accent', active: 'accent', star: 'accent', акцент: 'accent', важно: 'accent',\n  empty: 'empty', none: 'empty', пустой: 'empty',\n};\n\n/** Поля события: строки `key:: value` сразу под строкой даты. */\nconst EVENT_FIELDS = ['marker', 'label', 'tags', 'id', 'break'];\n/** Служебные строки шапки карточки: %% key: value %% */\nconst CARD_META = ['color', 'badge', 'tags', 'status'];\n\nconst THEME_PRESETS = {\n  purple:   { label: 'Фиолетовая (по умолчанию)', color: '#8b5cf6' },\n  indigo:   { label: 'Индиго (как в Timeline Card)', color: '#6366b0' },\n  blue:     { label: 'Синяя', color: '#3b82f6' },\n  green:    { label: 'Зелёная', color: '#16a34a' },\n  red:      { label: 'Красная', color: '#e11d48' },\n  orange:   { label: 'Оранжевая', color: '#f97316' },\n  teal:     { label: 'Бирюзовая', color: '#0d9488' },\n  graphite: { label: 'Графитовая', color: '#6b7280' },\n};\n\nconst IMAGE_EXT = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'bmp', 'avif'];\nconst VIDEO_EXT = ['mp4', 'webm', 'mov', 'm4v', 'ogv', 'mkv'];\nconst AUDIO_EXT = ['mp3', 'wav', 'm4a', 'ogg', 'oga', 'flac', 'opus', 'aac'];\n\nconst DEFAULT_SETTINGS = {\n  // ключи совпадают с Timeline Card — при первом запуске его настройки переносятся\n  mediaSize: 140,\n  showMediaCaptions: true,\n  autoDate: true,\n  dateFormat: 'YYYY-MM-DD HH:mm',\n  dateLocale: 'ru',\n  theme: 'purple',\n  customColor: '#8b5cf6',\n  collapseLongText: false,  // собственный текст события показывается как есть\n  collapseMaxLines: 3,\n  // новое в v3\n  sortMode: 'file',          // file | asc | desc\n  groupByYear: true,\n  insertMode: 'date',        // date | end\n  autoBreakDays: 0,          // 0 — выкл\n  humanDates: true,          // показывать «3 января 2026» вместо исходной строки\n  showIds: true,\n  linkedTags: true,         // теги из заметок, на которые ссылается событие\n  linkedMedia: true,        // картинки и видео из этих заметок\n  linkedExcerpt: true,      // текст заметки в карточке, если в тексте события только ссылка\n  excerptLines: 4,          // сколько строк текста заметки показывать\n  excerptLength: 1200,      // сколько текста заметки читать, символов\n  linkBrackets: false,      // показывать [[ ]] вокруг ссылок в тексте\n  showSearch: true,\n  formOpenByDefault: false,\n  maxWidth: 720,\n};\n\nmodule.exports = {\n  BLOCK_LANGUAGE, LEGACY_LANGUAGE, BLOCK_LANGUAGES, PROPS_VIEW_TYPE, HOVER_SOURCE, MARKERS, MARKER_ORDER, MARKER_ALIASES,\n  EVENT_FIELDS, CARD_META, THEME_PRESETS, IMAGE_EXT, VIDEO_EXT, AUDIO_EXT, DEFAULT_SETTINGS,\n};\n","modals/ConfirmModal":"'use strict';\n\nconst { Modal } = require('obsidian');\n\nclass ConfirmModal extends Modal {\n  constructor(app, { title, message, confirmText = 'Удалить', danger = true, onConfirm }) {\n    super(app);\n    this.opts = { title, message, confirmText, danger, onConfirm };\n  }\n  onOpen() {\n    const { title, message, confirmText, danger, onConfirm } = this.opts;\n    this.titleEl.setText(title);\n    this.contentEl.createEl('p', { text: message });\n    const row = this.contentEl.createDiv({ cls: 'modal-button-container' });\n    row.createEl('button', { text: 'Отмена' }).addEventListener('click', () => this.close());\n    const ok = row.createEl('button', { text: confirmText, cls: danger ? 'mod-warning' : 'mod-cta' });\n    ok.addEventListener('click', () => { this.close(); onConfirm(); });\n  }\n  onClose() {\n    this.contentEl.empty();\n  }\n}\n\nfunction confirm(app, opts) {\n  return new Promise((resolve) => {\n    const modal = new ConfirmModal(app, { ...opts, onConfirm: () => resolve(true) });\n    const origClose = modal.onClose.bind(modal);\n    modal.onClose = () => { origClose(); setTimeout(() => resolve(false), 0); };\n    modal.open();\n  });\n}\n\nmodule.exports = { ConfirmModal, confirm };\n","modals/VaultFileModal":"'use strict';\n\nconst { FuzzySuggestModal } = require('obsidian');\n\n/** Выбор существующего файла хранилища (медиа/документа) для прикрепления к событию. */\nclass VaultFileModal extends FuzzySuggestModal {\n  constructor(app, onChoose, filter) {\n    super(app);\n    this.onChoose = onChoose;\n    this.filter = filter || ((f) => f.extension !== 'md' && f.extension !== 'canvas');\n    this.setPlaceholder('Найдите файл в хранилище…');\n  }\n  getItems() {\n    return this.app.vault.getFiles().filter(this.filter).sort((a, b) => b.stat.mtime - a.stat.mtime);\n  }\n  getItemText(file) {\n    return file.path;\n  }\n  onChooseItem(file) {\n    this.onChoose(file);\n  }\n}\n\nmodule.exports = { VaultFileModal };\n","model/linkedTags":"'use strict';\n\n/*\n * Данные из заметок, на которые ссылается событие ([[Николас Мадуро]]):\n *   - теги заметки (свойство tags и #теги в тексте);\n *   - картинки и видео, встроенные в заметку (![[фото.jpg]]);\n *   - список связанных заметок — для фрагмента текста «под катом».\n */\n\nconst { getAllTags, TFile } = require('obsidian');\nconst { extractWikiLinks } = require('./parser');\nconst { IMAGE_EXT, VIDEO_EXT } = require('../constants');\n\nconst MAX_LINKED_MEDIA = 12;\n\nfunction tagsOfFile(app, file) {\n  const cache = app.metadataCache.getFileCache(file);\n  if (!cache) return [];\n  const raw = (getAllTags ? getAllTags(cache) : (cache.tags || []).map((t) => t.tag)) || [];\n  return raw.map((t) => t.replace(/^#/, '')).filter(Boolean);\n}\n\n/** Картинки и видео, встроенные в заметку (по кэшу метаданных, без чтения файла). */\nfunction mediaOfFile(app, file) {\n  const cache = app.metadataCache.getFileCache(file);\n  const out = [];\n  for (const embed of (cache && cache.embeds) || []) {\n    const link = embed.link.split('#')[0];\n    const target = app.metadataCache.getFirstLinkpathDest(link, file.path);\n    if (!(target instanceof TFile)) continue;\n    const ext = target.extension.toLowerCase();\n    const kind = IMAGE_EXT.includes(ext) ? 'image' : VIDEO_EXT.includes(ext) ? 'video' : null;\n    if (!kind) continue;\n    const alt = embed.displayText && embed.displayText !== embed.link && !/^\\d+(x\\d+)?$/.test(embed.displayText) ? embed.displayText : '';\n    out.push({ file: target, link: embed.link, alt, kind, from: file.basename });\n  }\n  return out;\n}\n\n/**\n * Проставляет событиям карточки:\n *   ev.linkedNotes  — TFile заметок, на которые ссылается событие\n *   ev.linkedPaths  — их пути (для обновления при изменении)\n *   ev.linkedTags   — [{ tag, from: ['Заметка'] }] без тегов, уже указанных у события\n *   ev.linkedMedia  — картинки и видео из этих заметок\n * opts: { tags: bool, media: bool }\n */\nfunction annotateLinkedTags(app, card, sourcePath, opts) {\n  const o = typeof opts === 'object' && opts ? opts : { tags: !!opts, media: false };\n  for (const ev of card.entries) {\n    if (ev.type !== 'event') continue;\n    ev.linkedNotes = [];\n    ev.linkedPaths = [];\n    ev.linkedTags = [];\n    ev.linkedMedia = [];\n    const own = new Set(ev.tags.map((t) => t.toLowerCase()));\n    const byTag = new Map();\n    const seenMedia = new Set();\n    for (const target of extractWikiLinks(`${ev.title}\\n${ev.body}`)) {\n      const file = app.metadataCache.getFirstLinkpathDest(target, sourcePath);\n      if (!(file instanceof TFile) || file.extension !== 'md' || file.path === sourcePath) continue;\n      if (ev.linkedPaths.includes(file.path)) continue;\n      ev.linkedNotes.push(file);\n      ev.linkedPaths.push(file.path);\n      if (o.tags) {\n        for (const tag of tagsOfFile(app, file)) {\n          const key = tag.toLowerCase();\n          if (own.has(key)) continue;\n          if (!byTag.has(key)) byTag.set(key, { tag, from: [] });\n          const entry = byTag.get(key);\n          if (!entry.from.includes(file.basename)) entry.from.push(file.basename);\n        }\n      }\n      if (o.media) {\n        for (const m of mediaOfFile(app, file)) {\n          if (seenMedia.has(m.file.path) || ev.linkedMedia.length >= MAX_LINKED_MEDIA) continue;\n          seenMedia.add(m.file.path);\n          ev.linkedMedia.push(m);\n        }\n      }\n    }\n    ev.linkedTags = [...byTag.values()];\n  }\n  return card;\n}\n\n/** Все теги события: собственные + из связанных заметок. */\nfunction allTags(ev) {\n  return [...ev.tags, ...((ev.linkedTags || []).map((t) => t.tag))];\n}\n\n/**\n * Текст события состоит только из ссылок на заметки (знаки препинания не в счёт)?\n * Тогда под ним показывается фрагмент связанной заметки.\n */\nfunction isLinkOnly(text) {\n  const t = String(text || '');\n  if (!/\\[\\[[^\\]]+\\]\\]/.test(t)) return false;\n  return t.replace(/!?\\[\\[[^\\]]+\\]\\]/g, '').replace(/[\\s.,;:!?—–\\-•*_>()]/g, '') === '';\n}\n\n/**\n * Фрагмент текста заметки: без свойств, встраиваний медиа и пустых строк,\n * по целым абзацам до ~limit символов. { text, truncated, words }\n */\nasync function noteExcerpt(app, file, limit) {\n  let content = await app.vault.cachedRead(file);\n  const cache = app.metadataCache.getFileCache(file);\n  if (cache && cache.frontmatterPosition) content = content.slice(cache.frontmatterPosition.end.offset);\n  else content = content.replace(/^---\\n[\\s\\S]*?\\n---\\n?/, '');\n  content = content\n    .replace(/!\\[\\[[^\\]]+\\]\\]/g, (m) => {\n      const ext = m.slice(3, -2).split('|')[0].split('.').pop().toLowerCase();\n      return IMAGE_EXT.includes(ext) || VIDEO_EXT.includes(ext) ? '' : m;\n    })\n    .replace(/%%[\\s\\S]*?%%/g, '')\n    .replace(/\\n{3,}/g, '\\n\\n')\n    .trim();\n  // заголовок, повторяющий имя заметки, не нужен — оно уже в шапке ката\n  const h1 = content.match(/^#\\s+(.+)\\n*/);\n  if (h1 && h1[1].trim().toLowerCase() === file.basename.toLowerCase()) content = content.slice(h1[0].length).trim();\n  const words = content ? content.split(/\\s+/).length : 0;\n  if (content.length <= limit) return { text: content, truncated: false, words };\n  const paras = content.split(/\\n{2,}/);\n  let out = '';\n  for (const p of paras) {\n    const sep = out ? '\\n\\n' : '';\n    if (out.length + sep.length + p.length <= limit) { out += sep + p; continue; }\n    const room = limit - out.length - sep.length;\n    if (room > limit * 0.3 || !out) {\n      // абзац не влезает целиком — режем по предложению, иначе по слову\n      const cut = p.slice(0, Math.max(room, 1));\n      const dot = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));\n      const space = cut.lastIndexOf(' ');\n      const end = dot > room * 0.5 ? dot + 1 : space > room * 0.5 ? space : cut.length;\n      const piece = cut.slice(0, end).trimEnd();\n      out += `${sep}${piece}${/[.!?]$/.test(piece) ? '' : '…'}`;\n    }\n    break;\n  }\n  // не заканчиваем фрагмент «висящим» заголовком\n  out = out.replace(/(\\n\\n#{1,6}\\s[^\\n]*)+$/, '');\n  return { text: out, truncated: true, words };\n}\n\n/**\n * Markdown -> простой текст с сохранением переносов строк:\n * без разметки выносок/цитат, заголовков, выделения, ссылок (остаётся их текст),\n * встраиваний, комментариев, HTML и ограждений кода.\n */\nfunction markdownToPlain(md) {\n  // [ \\t] вместо \\s в якорях ^ — чтобы не «съедать» пустые строки между абзацами\n  return String(md || '')\n    .replace(/\\r\\n?/g, '\\n')\n    .replace(/^[ \\t]*(```|~~~).*$/gm, '')                         // ограждения кода\n    .replace(/%%[\\s\\S]*?%%/g, '')                                 // комментарии Obsidian\n    .replace(/<!--[\\s\\S]*?-->/g, '')\n    .replace(/^[ \\t]*>[ \\t]*\\[![^\\]]+\\][+-]?[ \\t]*(.*)$/gm, '$1')  // заголовок выноски: только его текст\n    .replace(/^([ \\t]*>)+[ \\t]?/gm, '')                           // маркеры цитат\n    .replace(/^[ \\t]{0,3}#{1,6}[ \\t]+/gm, '')                     // заголовки\n    .replace(/^[ \\t]*[-*+][ \\t]+\\[[ xX]\\][ \\t]+/gm, '• ')         // задачи\n    .replace(/^([ \\t]*)[-*+][ \\t]+/gm, '$1• ')                    // маркированные списки\n    .replace(/^[ \\t]*(-{3,}|\\*{3,}|_{3,})[ \\t]*$/gm, '')          // горизонтальные линии\n    .replace(/!\\[\\[[^\\]]*\\]\\]/g, '')                              // встраивания\n    .replace(/!\\[[^\\]]*\\]\\([^)]*\\)/g, '')                         // картинки markdown\n    .replace(/\\[\\[([^\\]|]+)\\|([^\\]]+)\\]\\]/g, '$2')                // [[цель|текст]]\n    .replace(/\\[\\[([^\\]]+)\\]\\]/g, (m, t) => t.split('#').pop().replace(/^\\^/, ''))\n    .replace(/\\[([^\\]]+)\\]\\([^)]*\\)/g, '$1')                      // [текст](url)\n    .replace(/<[^>]+>/g, '')                                      // HTML\n    .replace(/(\\*\\*|__)(.+?)\\1/g, '$2')                           // жирный\n    .replace(/(^|[^\\w*])[*_]([^*_\\n]+)[*_](?=[^\\w*]|$)/gm, '$1$2') // курсив\n    .replace(/~~(.+?)~~/g, '$1')\n    .replace(/==(.+?)==/g, '$1')\n    .replace(/`([^`]+)`/g, '$1')\n    .replace(/(^|[ \\t])#[\\p{L}\\p{N}_/-]+/gmu, '$1')               // #теги\n    .replace(/(\\S)[ \\t]{2,}/g, '$1 ')\n    .replace(/[ \\t]+$/gm, '')\n    .replace(/\\n{3,}/g, '\\n\\n')\n    .trim();\n}\n\n\nmodule.exports = { markdownToPlain, annotateLinkedTags, allTags, tagsOfFile, mediaOfFile, isLinkOnly, noteExcerpt };\n","model/parser":"'use strict';\n\n/*\n * Разбор содержимого блока ```timeline (и устаревшего ```track).\n *\n * Совместимо с Timeline Card v2:\n *   ## Заголовок карточки\n *   %% color: green %%\n *   #### Секция\n *   ### !Событие          (! — акцентный маркер)\n *   Строка даты (всегда первая строка после ###, может быть пустой)\n *   Текст события…\n *\n * Новое в v3 (всё необязательно):\n *   %% badge: Справочник %%   %% tags: #a #b %%   %% status: Проверено %%\n *   Любые строки до первого события/секции — описание карточки.\n *   Под строкой даты: marker:: done | warning | info | accent | empty\n *                     label:: Тревога / Финансы\n *                     tags:: #экономика #бюджет\n *                     id:: fin-2026-02\n *                     break:: Период консультаций   (разрыв линии перед событием)\n */\n\nconst { MARKER_ALIASES, EVENT_FIELDS, CARD_META } = require('../constants');\nconst { parseDate } = require('../utils/dates');\nconst { parseTags } = require('../utils/text');\n\nconst FIELD_RE = /^\\s*([A-Za-z_-]+)::\\s?(.*)$/;\nconst META_RE = /^%%\\s*([A-Za-z_-]+)\\s*:\\s*(.*?)\\s*%%\\s*$/;\nconst FENCE_RE = /^\\s*(```|~~~)/;\n\nfunction trimEmptyEdges(lines) {\n  let a = 0;\n  let b = lines.length;\n  while (a < b && lines[a].trim() === '') a++;\n  while (b > a && lines[b - 1].trim() === '') b--;\n  return lines.slice(a, b);\n}\n\nfunction normalizeMarker(value) {\n  const key = String(value || '').trim().toLowerCase();\n  return MARKER_ALIASES[key] || null;\n}\n\nfunction newEvent(title) {\n  return {\n    type: 'event', title, date: '', marker: 'empty', label: '', tags: [], id: '',\n    breakText: null, body: '', _bodyLines: [],\n  };\n}\n\nfunction parseCard(source) {\n  const lines = String(source || '').replace(/\\r\\n?/g, '\\n').split('\\n');\n  const card = { title: '', color: '', badge: '', tags: [], status: '', description: '', entries: [] };\n  const descLines = [];\n  let current = null;\n  let stage = 'body'; // date | fields | body (для текущего события)\n  let inFence = false;\n\n  const flush = () => {\n    if (!current) return;\n    current.body = trimEmptyEdges(current._bodyLines).join('\\n');\n    delete current._bodyLines;\n    card.entries.push(current);\n    current = null;\n  };\n\n  for (const line of lines) {\n    if (inFence) {\n      if (FENCE_RE.test(line)) inFence = false;\n      current._bodyLines.push(line);\n      continue;\n    }\n\n    const noEntriesYet = !current && card.entries.length === 0;\n\n    if (noEntriesYet && /^##\\s/.test(line) && !card.title) {\n      card.title = line.replace(/^##\\s+/, '').trim();\n      continue;\n    }\n    if (!current) {\n      const meta = line.match(META_RE);\n      if (meta && CARD_META.includes(meta[1].toLowerCase())) {\n        const key = meta[1].toLowerCase();\n        if (key === 'tags') card.tags = parseTags(meta[2]);\n        else card[key] = meta[2].trim();\n        continue;\n      }\n    }\n    if (/^####\\s/.test(line)) {\n      flush();\n      card.entries.push({ type: 'section', label: line.replace(/^####\\s+/, '').trim() });\n      continue;\n    }\n    if (/^###\\s/.test(line)) {\n      flush();\n      let title = line.replace(/^###\\s+/, '').trim();\n      let accent = false;\n      if (title.startsWith('!')) { accent = true; title = title.slice(1).trim(); }\n      current = newEvent(title);\n      if (accent) current.marker = 'accent';\n      stage = 'date';\n      continue;\n    }\n    if (!current) {\n      if (card.entries.length === 0) descLines.push(line);\n      continue;\n    }\n    if (stage === 'date') {\n      current.date = line.trim();\n      stage = 'fields';\n      continue;\n    }\n    if (stage === 'fields') {\n      const f = line.match(FIELD_RE);\n      const key = f && f[1].toLowerCase();\n      if (f && EVENT_FIELDS.includes(key)) {\n        const value = f[2].trim();\n        if (key === 'marker') current.marker = normalizeMarker(value) || current.marker;\n        else if (key === 'tags') current.tags = parseTags(value);\n        else if (key === 'break') current.breakText = value;\n        else current[key] = value;\n        continue;\n      }\n      stage = 'body';\n    }\n    if (FENCE_RE.test(line)) inFence = true;\n    current._bodyLines.push(line);\n  }\n  flush();\n  card.description = trimEmptyEdges(descLines).join('\\n');\n  resolveDates(card);\n  return card;\n}\n\n/**\n * Разбор дат событий в порядке заметки. Даты без года («начало октября»,\n * «12 октября») получают год от предыдущего события с датой, а если его нет —\n * от следующего.\n */\nfunction resolveDates(card) {\n  const events = card.entries.filter((e) => e.type === 'event');\n  let prev = null;\n  for (const ev of events) {\n    ev.dateSpec = parseDate(ev.date, { prev });\n    if (ev.dateSpec.valid) prev = ev.dateSpec;\n  }\n  let next = null;\n  for (let i = events.length - 1; i >= 0; i--) {\n    const ev = events[i];\n    if (ev.dateSpec.needsYear) ev.dateSpec = parseDate(ev.date, { next, fallbackYear: new Date().getFullYear() });\n    if (ev.dateSpec.valid) next = ev.dateSpec;\n  }\n}\n\n/** Все события карточки (без секций). */\nfunction eventsOf(card) {\n  return card.entries.filter((e) => e.type === 'event');\n}\n\n/** Wiki-ссылки (не встраивания) из текста: [[Цель|Алиас]] -> 'Цель'. */\nfunction extractWikiLinks(text) {\n  const out = [];\n  const re = /(!?)\\[\\[([^\\]\\n]+?)\\]\\]/g;\n  let m;\n  while ((m = re.exec(String(text || '')))) {\n    if (m[1]) continue;\n    const target = m[2].split('|')[0].split('#')[0].trim();\n    if (target && !out.includes(target)) out.push(target);\n  }\n  return out;\n}\n\n/** Все блоки таймлайна в тексте заметки: [{ source, language, lineStart, lineEnd }] (номера строк ограждений). */\nfunction findTrackBlocks(content, languages) {\n  const langs = Array.isArray(languages) ? languages : [languages];\n  const lines = String(content || '').split('\\n');\n  const blocks = [];\n  let open = null;\n  lines.forEach((line, i) => {\n    if (!open) {\n      const m = line.match(/^(\\s*)(`{3,}|~{3,})\\s*([\\w-]+)\\s*$/);\n      if (m && langs.includes(m[3])) open = { fence: m[2], start: i, language: m[3] };\n    } else if (line.trim().startsWith(open.fence) && line.trim().replace(/[`~]/g, '') === '') {\n      blocks.push({ source: lines.slice(open.start + 1, i).join('\\n'), language: open.language, lineStart: open.start, lineEnd: i });\n      open = null;\n    }\n  });\n  return blocks;\n}\n\nmodule.exports = { parseCard, resolveDates, eventsOf, extractWikiLinks, findTrackBlocks, normalizeMarker };\n","model/serializer":"'use strict';\n\n/* Обратная сборка блока ```track из модели (см. parser.js). */\n\nconst { parseDate } = require('../utils/dates');\n\nfunction serializeEvent(ev) {\n  const lines = [`### ${ev.marker === 'accent' ? '!' : ''}${(ev.title || '').trim()}`];\n  lines.push((ev.date || '').trim());\n  if (ev.marker && ev.marker !== 'empty' && ev.marker !== 'accent') lines.push(`marker:: ${ev.marker}`);\n  if (ev.label) lines.push(`label:: ${ev.label.trim()}`);\n  if (ev.tags && ev.tags.length) lines.push(`tags:: ${ev.tags.map((t) => '#' + t).join(' ')}`);\n  if (ev.id) lines.push(`id:: ${ev.id.trim()}`);\n  if (ev.breakText != null) lines.push(`break:: ${ev.breakText.trim()}`.trimEnd());\n  const body = (ev.body || '').replace(/\\s+$/, '');\n  if (body) lines.push(body);\n  return lines.join('\\n');\n}\n\nfunction serializeCard(card) {\n  const head = [];\n  if (card.title) head.push(`## ${card.title.trim()}`);\n  if (card.color) head.push(`%% color: ${card.color} %%`);\n  if (card.badge) head.push(`%% badge: ${card.badge} %%`);\n  if (card.tags && card.tags.length) head.push(`%% tags: ${card.tags.map((t) => '#' + t).join(' ')} %%`);\n  if (card.status) head.push(`%% status: ${card.status} %%`);\n  if (card.description) head.push(card.description.replace(/\\s+$/, ''));\n\n  const parts = [];\n  if (head.length) parts.push(head.join('\\n'));\n  for (const entry of card.entries) {\n    parts.push(entry.type === 'section' ? `#### ${entry.label || ''}` : serializeEvent(entry));\n  }\n  return parts.join('\\n\\n');\n}\n\n/**\n * Позиция вставки нового события.\n * mode 'date': после последнего события с датой <= новой (секции не пересекаем вперёд);\n * нераспознанная дата или mode 'end' — в конец.\n */\nfunction insertIndex(card, ev, mode) {\n  const n = card.entries.length;\n  if (mode !== 'date') return n;\n  const spec = parseDate(ev.date);\n  if (!spec.valid) return n;\n  let lastLE = -1;\n  let firstEvent = -1;\n  card.entries.forEach((e, i) => {\n    if (e.type !== 'event') return;\n    if (firstEvent < 0) firstEvent = i;\n    const s = e.dateSpec || parseDate(e.date);\n    if (s.valid && s.sortKey <= spec.sortKey) lastLE = i;\n  });\n  if (lastLE >= 0) return lastLE + 1;\n  if (firstEvent >= 0) {\n    // все события позже нового — ставим перед первым событием (после ведущей секции, если есть)\n    return firstEvent;\n  }\n  return n;\n}\n\nmodule.exports = { serializeCard, serializeEvent, insertIndex };\n","model/stats":"'use strict';\n\n/* Сводка по карточкам: период, счётчики маркеров, wiki-ссылки — для панели свойств и графа. */\n\nconst { MARKER_ORDER } = require('../constants');\nconst { eventsOf, extractWikiLinks } = require('./parser');\n\nfunction cardStats(cards) {\n  const counts = Object.fromEntries(MARKER_ORDER.map((k) => [k, 0]));\n  const links = new Map(); // цель -> число упоминаний\n  let min = null;\n  let max = null;\n  let total = 0;\n  const statuses = [];\n  const tags = new Set();\n\n  for (const card of cards) {\n    if (card.status) statuses.push(card.status);\n    card.tags.forEach((t) => tags.add(t));\n    for (const ev of eventsOf(card)) {\n      total++;\n      counts[ev.marker] = (counts[ev.marker] || 0) + 1;\n      ev.tags.forEach((t) => tags.add(t));\n      (ev.linkedTags || []).forEach((t) => tags.add(t.tag));\n      const s = ev.dateSpec;\n      if (s && s.valid) {\n        if (min == null || s.startIdx < min) min = s.startIdx;\n        if (max == null || s.endIdx > max) max = s.endIdx;\n      }\n      for (const l of extractWikiLinks(`${ev.title}\\n${ev.body}`)) links.set(l, (links.get(l) || 0) + 1);\n    }\n  }\n  return { counts, links, min, max, total, statuses, tags: [...tags] };\n}\n\n/** Граф: узлы событий и страниц, рёбра событие -> страница. */\nfunction buildGraph(cards) {\n  const nodes = [];\n  const edges = [];\n  const pageIndex = new Map();\n  cards.forEach((card, ci) => {\n    let prevEvent = null;\n    card.entries.forEach((ev, ei) => {\n      if (ev.type !== 'event') return;\n      const evNode = { id: `e${ci}-${ei}`, kind: 'event', label: ev.title || '(без названия)', marker: ev.marker, card: ci, entry: ei };\n      nodes.push(evNode);\n      // слабая связь соседних событий — граф не распадается на острова\n      if (prevEvent) edges.push({ from: prevEvent.id, to: evNode.id, weak: true });\n      prevEvent = evNode;\n      for (const target of extractWikiLinks(`${ev.title}\\n${ev.body}`)) {\n        let pn = pageIndex.get(target);\n        if (!pn) {\n          pn = { id: `p${pageIndex.size}`, kind: 'page', label: target, degree: 0 };\n          pageIndex.set(target, pn);\n          nodes.push(pn);\n        }\n        pn.degree++;\n        edges.push({ from: evNode.id, to: pn.id });\n      }\n    });\n  });\n  return { nodes, edges };\n}\n\nmodule.exports = { cardStats, buildGraph };\n","model/store":"'use strict';\n\n/* Запись изменённой карточки обратно в заметку. */\n\nconst { TFile, Notice } = require('obsidian');\nconst { BLOCK_LANGUAGES } = require('../constants');\nconst { findTrackBlocks } = require('./parser');\nconst { serializeCard } = require('./serializer');\n\nconst norm = (s) => String(s || '').replace(/\\r\\n?/g, '\\n').replace(/\\s+$/, '');\n\n/**\n * Находит блок в тексте заметки: сначала по номеру строки из getSectionInfo,\n * затем по совпадению исходного текста, затем по порядковому номеру.\n */\nfunction locateBlock(content, hint) {\n  const blocks = findTrackBlocks(content, BLOCK_LANGUAGES);\n  if (!blocks.length) return null;\n  if (hint.lineStart != null) {\n    const byLine = blocks.find((b) => b.lineStart === hint.lineStart);\n    if (byLine && (hint.source == null || norm(byLine.source) === norm(hint.source))) return byLine;\n  }\n  if (hint.source != null) {\n    const bySource = blocks.find((b) => norm(b.source) === norm(hint.source));\n    if (bySource) return bySource;\n  }\n  if (hint.index != null && blocks[hint.index]) return blocks[hint.index];\n  if (hint.lineStart != null) return blocks.find((b) => b.lineStart === hint.lineStart) || null;\n  return null;\n}\n\n/**\n * @param app\n * @param {string} path      путь заметки\n * @param {object} hint      { lineStart?, source?, index? }\n * @param {object} card      модель карточки\n * @returns {Promise<string>} новый исходный текст блока\n */\nasync function saveCard(app, path, hint, card) {\n  const file = app.vault.getAbstractFileByPath(path);\n  if (!(file instanceof TFile)) {\n    new Notice('Event Timeline: заметка не найдена');\n    return null;\n  }\n  const inner = serializeCard(card);\n  let ok = false;\n  await app.vault.process(file, (data) => {\n    const block = locateBlock(data, hint);\n    if (!block) return data;\n    ok = true;\n    const lines = data.split('\\n');\n    return [...lines.slice(0, block.lineStart + 1), inner, ...lines.slice(block.lineEnd)].join('\\n');\n  });\n  if (!ok) new Notice('Event Timeline: не удалось найти блок в заметке — изменения не сохранены');\n  return ok ? inner : null;\n}\n\n/** Сохранить «сырой» текст блока (режим «Исходный код»). */\nasync function saveRaw(app, path, hint, text) {\n  const file = app.vault.getAbstractFileByPath(path);\n  if (!(file instanceof TFile)) return false;\n  let ok = false;\n  await app.vault.process(file, (data) => {\n    const block = locateBlock(data, hint);\n    if (!block) return data;\n    ok = true;\n    const lines = data.split('\\n');\n    return [...lines.slice(0, block.lineStart + 1), norm(text), ...lines.slice(block.lineEnd)].join('\\n');\n  });\n  if (!ok) new Notice('Event Timeline: не удалось найти блок в заметке');\n  return ok;\n}\n\nmodule.exports = { saveCard, saveRaw, locateBlock };\n","plugin":"'use strict';\n\n/* Сборка плагина: настройки, обработчики блоков, панель свойств, команды. */\n\nconst { Notice, MarkdownView } = require('obsidian');\nconst { BLOCK_LANGUAGE, LEGACY_LANGUAGE, PROPS_VIEW_TYPE, HOVER_SOURCE } = require('./constants');\nconst { loadSettings, SettingsTab } = require('./settings');\nconst { TimelineBlock } = require('./render/TimelineBlock');\nconst { PropertiesView } = require('./view/PropertiesView');\nconst { autoDateString } = require('./render/eventForm');\nconst { debounce } = require('./utils/text');\n\nfunction template(settings) {\n  const date = autoDateString(settings) || new Date().toISOString().slice(0, 10);\n  return [\n    `\\`\\`\\`${BLOCK_LANGUAGE}`,\n    '## Новый таймлайн',\n    '%% tags: #хроника %%',\n    'Краткое описание: о чём эта хроника.',\n    '',\n    '### Первое событие',\n    date,\n    'marker:: info',\n    'Текст события — markdown и [[ссылки на заметки]].',\n    '```',\n    '',\n  ].join('\\n');\n}\n\nasync function bootstrap(plugin) {\n  const { app } = plugin;\n  await loadSettings(plugin);\n\n  plugin.blocks = new Set();\n  plugin.uiStates = new Map();\n\n  plugin.getUiState = (key) => {\n    if (!plugin.uiStates.has(key)) {\n      plugin.uiStates.set(key, {\n        mode: 'timeline', query: '', sortMode: plugin.settings.sortMode,\n        expanded: new Set(), formOpen: !!plugin.settings.formOpenByDefault,\n      });\n    }\n    return plugin.uiStates.get(key);\n  };\n  plugin.resetUiSort = () => plugin.uiStates.forEach((s) => { s.sortMode = plugin.settings.sortMode; });\n  plugin.refreshAll = () => plugin.blocks.forEach((b) => { if (b.containerEl.isConnected) b.render(); });\n\n  /* ---- блоки ---- */\n  const register = (language) => {\n    try {\n      plugin.registerMarkdownCodeBlockProcessor(language, (source, el, ctx) => {\n        ctx.addChild(new TimelineBlock(plugin, source, el, ctx, language));\n      });\n      return true;\n    } catch (err) {\n      console.warn(`[Event Timeline] не удалось зарегистрировать блок ${language}`, err);\n      return false;\n    }\n  };\n  register(BLOCK_LANGUAGE);\n  const legacyOk = register(LEGACY_LANGUAGE);\n  const legacyEnabled = app.plugins && app.plugins.enabledPlugins && app.plugins.enabledPlugins.has('timeline-card');\n  if (!legacyOk || legacyEnabled) {\n    new Notice('Event Timeline: включён старый плагин Timeline Card. Отключите его, чтобы блоки ```track показывались в новом виде.', 12000);\n  }\n\n  // теги связанных заметок поменялись — перерисовать таймлайны, которые на них ссылаются\n  const changed = new Set();\n  const flush = debounce(() => {\n    plugin.blocks.forEach((b) => {\n      if (b.containerEl.isConnected && b.linkedPaths && [...changed].some((p) => b.linkedPaths.has(p))) b.render();\n    });\n    changed.clear();\n  }, 800);\n  plugin.registerEvent(app.metadataCache.on('changed', (file) => {\n    if (!plugin.settings.linkedTags) return;\n    changed.add(file.path);\n    flush();\n  }));\n\n  plugin.registerHoverLinkSource(HOVER_SOURCE, { display: 'Event Timeline', defaultMod: true });\n  plugin.addSettingTab(new SettingsTab(app, plugin));\n\n  /* ---- панель свойств ---- */\n  plugin.registerView(PROPS_VIEW_TYPE, (leaf) => new PropertiesView(leaf, plugin));\n  const openProps = async () => {\n    let leaf = app.workspace.getLeavesOfType(PROPS_VIEW_TYPE)[0];\n    if (!leaf) {\n      leaf = app.workspace.getRightLeaf(false);\n      await leaf.setViewState({ type: PROPS_VIEW_TYPE, active: true });\n    }\n    app.workspace.revealLeaf(leaf);\n  };\n  plugin.addRibbonIcon('calendar-range', 'Свойства таймлайна', openProps);\n\n  /* ---- помощники для команд и панели ---- */\n  const blocksInActive = () => {\n    const view = app.workspace.getActiveViewOfType(MarkdownView);\n    const file = app.workspace.getActiveFile();\n    const list = [...plugin.blocks].filter((b) => b.containerEl.isConnected && (\n      view ? view.containerEl.contains(b.containerEl) : (file && b.sourcePath === file.path)));\n    if (list.length || !file) return list;\n    return [...plugin.blocks].filter((b) => b.containerEl.isConnected && b.sourcePath === file.path);\n  };\n  const firstBlock = () => {\n    const list = blocksInActive();\n    if (!list.length) new Notice('В активной заметке нет видимого таймлайна (```timeline или ```track)');\n    // ближайший к видимой области\n    return list.sort((a, b) => Math.abs(a.containerEl.getBoundingClientRect().top) - Math.abs(b.containerEl.getBoundingClientRect().top))[0];\n  };\n  plugin.focusQueryInActive = (q) => { const b = firstBlock(); if (b) { b.setQuery(q); b.containerEl.scrollIntoView({ block: 'start', behavior: 'smooth' }); } };\n  plugin.setModeInActive = (m) => { const b = firstBlock(); if (b) { b.setMode(m); b.containerEl.scrollIntoView({ block: 'start', behavior: 'smooth' }); } };\n  plugin.insertTemplateIntoActive = () => {\n    const view = app.workspace.getActiveViewOfType(MarkdownView);\n    if (!view) { new Notice('Откройте заметку в режиме редактирования'); return; }\n    view.editor.replaceSelection(template(plugin.settings));\n  };\n\n  /* ---- команды ---- */\n  plugin.addCommand({\n    id: 'insert-timeline',\n    name: 'Вставить таймлайн',\n    editorCallback: (editor) => editor.replaceSelection(template(plugin.settings)),\n  });\n  plugin.addCommand({\n    id: 'add-event',\n    name: 'Добавить событие в таймлайн',\n    hotkeys: [{ modifiers: ['Alt'], key: 'n' }],\n    checkCallback: (checking) => {\n      const has = blocksInActive().length > 0;\n      if (checking) return has;\n      const b = firstBlock();\n      if (b) b.openForm();\n      return true;\n    },\n  });\n  plugin.addCommand({\n    id: 'open-properties',\n    name: 'Открыть панель свойств таймлайна',\n    callback: openProps,\n  });\n  plugin.addCommand({\n    id: 'show-graph',\n    name: 'Показать граф связей таймлайна',\n    checkCallback: (checking) => {\n      if (checking) return blocksInActive().length > 0;\n      plugin.setModeInActive('graph');\n      return true;\n    },\n  });\n  plugin.addCommand({\n    id: 'search-events',\n    name: 'Поиск по событиям таймлайна',\n    checkCallback: (checking) => {\n      if (checking) return blocksInActive().length > 0;\n      const b = firstBlock();\n      if (b) { b.setMode('timeline'); setTimeout(() => b.searchInput && b.searchInput.focus(), 30); }\n      return true;\n    },\n  });\n  plugin.addCommand({\n    id: 'convert-track-to-timeline',\n    name: 'Перевести блоки ```track в ```timeline в текущей заметке',\n    editorCallback: (editor) => {\n      const text = editor.getValue();\n      const next = text.replace(/^(\\s*(?:`{3,}|~{3,}))\\s*track\\s*$/gm, `$1${BLOCK_LANGUAGE}`);\n      if (next === text) { new Notice('Блоков ```track нет'); return; }\n      editor.setValue(next);\n      new Notice('Блоки ```track переведены в ```timeline');\n    },\n  });\n\n  plugin.teardown = () => {\n    app.workspace.detachLeavesOfType(PROPS_VIEW_TYPE);\n    document.querySelectorAll('.tc-popover, .tc-suggest, .tc-lightbox').forEach((n) => n.remove());\n  };\n}\n\nmodule.exports = { bootstrap };\n","render/TimelineBlock":"'use strict';\n\n/*\n * Один отрисованный блок ```timeline / ```track.\n * Хранит состояние интерфейса (режим, поиск, сортировка) в плагине, чтобы оно\n * переживало перерисовку блока после каждого сохранения заметки.\n */\n\nconst { MarkdownRenderChild, Notice } = require('obsidian');\nconst { parseCard } = require('../model/parser');\nconst { insertIndex } = require('../model/serializer');\nconst { saveCard, saveRaw } = require('../model/store');\nconst { buildGraph } = require('../model/stats');\nconst { annotateLinkedTags } = require('../model/linkedTags');\nconst { resolveAccent, wireHoverPreview, autoResize } = require('../utils/dom');\nconst { renderHeader } = require('./header');\nconst { createEventForm } = require('./eventForm');\nconst { renderList } = require('./list');\nconst { renderGraph } = require('./graph');\n\nclass TimelineBlock extends MarkdownRenderChild {\n  constructor(plugin, source, el, ctx, language) {\n    super(el);\n    this.plugin = plugin;\n    this.app = plugin.app;\n    this.source = source;\n    this.ctx = ctx;\n    this.language = language;\n    this.sourcePath = ctx.sourcePath;\n    this.form = null;\n    this.searchInput = null;\n  }\n\n  onload() {\n    this.plugin.blocks.add(this);\n    this.ui = this.plugin.getUiState(this.uiKey());\n    this.render();\n  }\n\n  onunload() {\n    this.plugin.blocks.delete(this);\n  }\n\n  sectionInfo() {\n    try { return this.ctx.getSectionInfo(this.containerEl); } catch (e) { return null; }\n  }\n\n  uiKey() {\n    const info = this.sectionInfo();\n    if (info) return `${this.sourcePath}::${info.lineStart}`;\n    const m = this.source.match(/^##\\s+(.+)$/m);\n    return `${this.sourcePath}::${m ? m[1] : this.source.length}`;\n  }\n\n  hint() {\n    const info = this.sectionInfo();\n    return { lineStart: info ? info.lineStart : null, source: this.source };\n  }\n\n  get settings() {\n    return this.plugin.settings;\n  }\n\n  renderCtx() {\n    return { app: this.app, settings: this.settings, sourcePath: this.sourcePath, component: this, block: this };\n  }\n\n  /* ---------------- отрисовка ---------------- */\n\n  render() {\n    const el = this.containerEl;\n    el.empty();\n    el.addClass('tc-block-host');\n    this.card = annotateLinkedTags(this.app, parseCard(this.source), this.sourcePath, { tags: this.settings.linkedTags, media: this.settings.linkedMedia });\n    this.linkedPaths = new Set(this.card.entries.flatMap((e) => e.linkedPaths || []));\n    const root = el.createDiv({ cls: `tc-root is-mode-${this.ui.mode}` });\n    root.style.setProperty('--tc-accent', resolveAccent(this.card.color, this.settings));\n    root.style.setProperty('--tc-max-width', `${this.settings.maxWidth || 720}px`);\n    root.toggleClass('tc-link-brackets', !!this.settings.linkBrackets);\n    this.root = root;\n    wireHoverPreview(root, this.app, this.sourcePath);\n\n    renderHeader(root, this.card, this.renderCtx());\n\n    if (this.ui.mode === 'source') return this.renderSource(root);\n    if (this.ui.mode === 'graph') return this.renderGraphMode(root);\n\n    this.form = createEventForm(root, this.renderCtx(), {\n      collapsed: !this.ui.formOpen,\n      onSubmit: (data, index) => this.submitEvent(data, index),\n    });\n    this.form.el.addEventListener('click', () => { this.ui.formOpen = !this.form.el.hasClass('is-collapsed'); });\n    this.feedHost = root.createDiv({ cls: 'tc-feed-host' });\n    this.renderFeed();\n  }\n\n  renderFeed() {\n    if (!this.feedHost) return;\n    this.feedHost.empty();\n    renderList(this.feedHost, this.card, this.renderCtx());\n  }\n\n  renderSource(root) {\n    const box = root.createDiv({ cls: 'tc-source' });\n    const note = box.createDiv({ cls: 'tc-source-note' });\n    note.setText(`Содержимое блока \\`\\`\\`${this.language}. Формат описан в README (Настройки → Event Timeline).`);\n    const ta = box.createEl('textarea', { cls: 'tc-input tc-source-text', attr: { spellcheck: 'false' } });\n    ta.value = this.source;\n    setTimeout(() => autoResize(ta), 0);\n    ta.addEventListener('input', () => autoResize(ta));\n    const foot = box.createDiv({ cls: 'tc-form-foot' });\n    foot.createDiv({ cls: 'tc-field-hint', text: 'Cmd/Ctrl+Enter — сохранить' });\n    foot.createDiv({ cls: 'tc-spacer' });\n    const cancel = foot.createEl('button', { cls: 'tc-btn', text: 'К таймлайну' });\n    const save = foot.createEl('button', { cls: 'tc-btn tc-btn-primary', text: 'Сохранить' });\n    cancel.addEventListener('click', () => this.setMode('timeline'));\n    const doSave = async () => {\n      if (ta.value === this.source) { this.setMode('timeline'); return; }\n      this.ui.mode = 'timeline';\n      const ok = await saveRaw(this.app, this.sourcePath, this.hint(), ta.value);\n      if (!ok) this.ui.mode = 'source';\n    };\n    save.addEventListener('click', doSave);\n    ta.addEventListener('keydown', (e) => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); doSave(); } });\n  }\n\n  renderGraphMode(root) {\n    const graph = buildGraph([this.card]);\n    const resolved = (label) => !!this.app.metadataCache.getFirstLinkpathDest(label, this.sourcePath);\n    const box = root.createDiv({ cls: 'tc-graph-box' });\n    renderGraph(box, graph, {\n      width: 720, height: 460, resolved,\n      onPage: (n, ev) => this.app.workspace.openLinkText(n.label, this.sourcePath, ev.ctrlKey || ev.metaKey),\n      onEvent: (n) => this.revealEvent(n.entry),\n    });\n    const legend = box.createDiv({ cls: 'tc-graph-legend' });\n    legend.createSpan({ text: `${graph.nodes.filter((n) => n.kind === 'event').length} событий · ${graph.nodes.filter((n) => n.kind === 'page').length} заметок · ${graph.edges.filter((e) => !e.weak).length} связей` });\n    legend.createSpan({ cls: 'tc-field-hint', text: 'Клик по заметке — открыть, по событию — показать в таймлайне' });\n  }\n\n  /** Прокрутить к событию и подсветить его. */\n  revealEvent(index) {\n    if (this.ui.mode !== 'timeline' || this.ui.query) {\n      this.ui.mode = 'timeline';\n      this.ui.query = '';\n      this.render();\n    }\n    const row = this.root.querySelector(`.tc-event[data-index=\"${index}\"]`);\n    if (!row) return;\n    row.scrollIntoView({ block: 'center', behavior: 'smooth' });\n    row.addClass('is-flash');\n    setTimeout(() => row.removeClass('is-flash'), 1600);\n  }\n\n  /* ---------------- действия ---------------- */\n\n  setMode(mode) {\n    this.ui.mode = mode;\n    this.render();\n  }\n\n  setQuery(query, fromInput) {\n    this.ui.query = query || '';\n    if (!fromInput && this.searchInput) this.searchInput.value = this.ui.query;\n    if (this.ui.mode !== 'timeline') { this.ui.mode = 'timeline'; this.render(); return; }\n    this.renderFeed();\n  }\n\n  setSort(mode) {\n    this.ui.sortMode = mode;\n    this.renderFeed();\n  }\n\n  openForm(ev, index) {\n    if (this.ui.mode !== 'timeline') { this.ui.mode = 'timeline'; this.render(); }\n    this.ui.formOpen = true;\n    this.form.open(ev, index);\n  }\n\n  /** Применить изменение к свежей модели и записать в заметку. */\n  async mutate(fn) {\n    const card = parseCard(this.source);\n    fn(card);\n    const saved = await saveCard(this.app, this.sourcePath, this.hint(), card);\n    return saved != null;\n  }\n\n  async submitEvent(data, index) {\n    const ok = await this.mutate((card) => {\n      if (index != null && card.entries[index] && card.entries[index].type === 'event') {\n        card.entries[index] = data;\n      } else {\n        card.entries.splice(insertIndex(card, data, this.settings.insertMode), 0, data);\n      }\n    });\n    if (!ok) throw new Error('not saved');\n    this.ui.formOpen = false;\n    new Notice(index != null ? 'Событие обновлено' : 'Событие добавлено в таймлайн');\n  }\n\n  move(index, dir) {\n    return this.mutate((card) => {\n      const target = index + dir;\n      if (target < 0 || target >= card.entries.length) return;\n      const [item] = card.entries.splice(index, 1);\n      card.entries.splice(target, 0, item);\n    });\n  }\n}\n\nmodule.exports = { TimelineBlock };\n","render/collapse":"'use strict';\n\n/*\n * Сворачивание длинного текста события по числу строк.\n * Порог считается от line-height, а не сравнением scrollHeight/clientHeight\n * неограниченного блока (ошибка, исправленная в v2.4.1).\n */\n\nfunction setupCollapse(bodyEl, settings, { expanded, onToggle }) {\n  if (!settings.collapseLongText) return;\n  const measure = () => {\n    if (!bodyEl.isConnected) return;\n    const cs = window.getComputedStyle(bodyEl);\n    let lh = parseFloat(cs.lineHeight);\n    if (!lh || isNaN(lh)) lh = (parseFloat(cs.fontSize) || 15) * 1.6;\n    const threshold = Math.round(lh * Math.max(1, settings.collapseMaxLines || 4));\n    if (bodyEl.scrollHeight <= threshold + lh * 0.6) return;\n\n    bodyEl.style.setProperty('--tc-collapse-height', `${threshold}px`);\n    bodyEl.toggleClass('tc-clamped', !expanded);\n    const toggle = createDiv({ cls: 'tc-toggle' });\n    const label = toggle.createSpan();\n    const icon = toggle.createSpan({ cls: 'tc-toggle-icon' });\n    const sync = () => {\n      const clamped = bodyEl.hasClass('tc-clamped');\n      label.setText(clamped ? 'Показать полностью' : 'Свернуть');\n      icon.setText(clamped ? '⌄' : '⌃');\n    };\n    sync();\n    toggle.addEventListener('click', (e) => {\n      e.stopPropagation();\n      const clamped = bodyEl.toggleClass('tc-clamped', !bodyEl.hasClass('tc-clamped'));\n      sync();\n      if (onToggle) onToggle(!bodyEl.hasClass('tc-clamped'));\n      return clamped;\n    });\n    bodyEl.after(toggle);\n  };\n  // ждём раскладку (в Live Preview блок может быть ещё не в DOM)\n  requestAnimationFrame(() => requestAnimationFrame(measure));\n}\n\nmodule.exports = { setupCollapse };\n","render/eventCard":"'use strict';\n\n/* Карточка одного события: буллет на линии, шапка, текст, медиа, теги, ID. */\n\nconst { setIcon, Menu, MarkdownRenderer, Notice } = require('obsidian');\nconst { MARKERS, MARKER_ORDER } = require('../constants');\nconst { formatDate } = require('../utils/dates');\nconst { hashIndex } = require('../utils/text');\nconst { extractMedia, renderMediaSection } = require('./media');\nconst { isLinkOnly, noteExcerpt, markdownToPlain } = require('../model/linkedTags');\nconst { setupCollapse } = require('./collapse');\nconst { makeInlineInput, openInlineTextarea } = require('./inlineEdit');\nconst { confirm } = require('../modals/ConfirmModal');\n\nconst TAG_COLORS = 6;\n\nasync function renderMarkdown(app, md, el, sourcePath, component) {\n  if (MarkdownRenderer.render) await MarkdownRenderer.render(app, md, el, sourcePath, component);\n  else await MarkdownRenderer.renderMarkdown(md, el, sourcePath, component);\n}\n\nfunction renderBullet(parent, marker) {\n  const b = parent.createDiv({ cls: `tc-bullet is-${marker}` });\n  const m = MARKERS[marker] || MARKERS.empty;\n  if (m.icon) setIcon(b, m.icon);\n  return b;\n}\n\nfunction tagPill(parent, tag, onClick) {\n  const pill = parent.createSpan({ cls: `tc-tag tc-tag-c${hashIndex(tag, TAG_COLORS)}`, text: `#${tag}` });\n  if (onClick) pill.addEventListener('click', (e) => { e.stopPropagation(); onClick(tag); });\n  return pill;\n}\n\n/**\n * @param list     контейнер строк таймлайна\n * @param ev       событие (из parser)\n * @param index    индекс в card.entries\n * @param ctx      { app, settings, sourcePath, component, block }\n */\nfunction renderEventCard(list, ev, index, ctx) {\n  const { app, settings, sourcePath, component, block } = ctx;\n  const row = list.createDiv({ cls: `tc-row tc-event is-${ev.marker}` });\n  row.dataset.index = String(index);\n\n  /* --- буллет --- */\n  const rail = row.createDiv({ cls: 'tc-rail' });\n  const bullet = renderBullet(rail, ev.marker);\n  bullet.setAttr('aria-label', 'Тип буллета');\n  bullet.addEventListener('click', (e) => {\n    e.stopPropagation();\n    const menu = new Menu();\n    for (const key of MARKER_ORDER) {\n      menu.addItem((it) => it.setTitle(MARKERS[key].label).setIcon(MARKERS[key].icon || 'circle')\n        .setChecked(ev.marker === key)\n        .onClick(() => block.mutate((card) => { card.entries[index].marker = key; })));\n    }\n    menu.showAtMouseEvent(e);\n  });\n\n  const card = row.createDiv({ cls: 'tc-event-card' });\n\n  /* --- шапка --- */\n  const head = card.createDiv({ cls: 'tc-event-head' });\n  const titleEl = head.createDiv({ cls: 'tc-event-title' });\n  // заголовок может содержать [[ссылки]] — рендерим как markdown-строку\n  renderMarkdown(app, ev.title || '(без названия)', titleEl, sourcePath, component).then(() => {\n    const p = titleEl.querySelector('p');\n    if (p && titleEl.childElementCount === 1) p.replaceWith(...Array.from(p.childNodes));\n  });\n  makeInlineInput(titleEl, {\n    value: ev.title,\n    onSave: (v) => v && block.mutate((c) => { c.entries[index].title = v; }),\n  });\n\n  const meta = head.createDiv({ cls: 'tc-event-meta' });\n  if (ev.label) meta.createSpan({ cls: `tc-badge is-${ev.marker}`, text: ev.label });\n  const dateEl = meta.createDiv({ cls: 'tc-event-date' });\n  setIcon(dateEl.createSpan({ cls: 'tc-date-icon' }), 'calendar');\n  const dateText = dateEl.createSpan({ cls: 'tc-date-text' });\n  const human = settings.humanDates && ev.dateSpec && ev.dateSpec.valid;\n  dateText.setText(human ? formatDate(ev.dateSpec) : (ev.date || 'без даты'));\n  if (human && ev.date) dateEl.setAttr('aria-label', ev.date);\n  if (!ev.date) dateEl.addClass('is-empty');\n  makeInlineInput(dateEl, {\n    value: ev.date, cls: 'tc-mono',\n    onSave: (v) => block.mutate((c) => { c.entries[index].date = v; }),\n  });\n\n  /* --- текст --- */\n  const { text, items } = extractMedia(ev.body, app, sourcePath);\n  const bodyWrap = card.createDiv({ cls: 'tc-event-body-wrap' });\n  const showBody = () => {\n    bodyWrap.empty();\n    if (!text) {\n      const add = bodyWrap.createDiv({ cls: 'tc-body-add', text: '+ Добавить описание' });\n      add.addEventListener('click', (e) => { e.stopPropagation(); editBody(); });\n      return;\n    }\n    const bodyEl = bodyWrap.createDiv({ cls: 'tc-event-body markdown-rendered' });\n    const onlyLink = settings.linkedExcerpt && isLinkOnly(text) && (ev.linkedNotes || []).length > 0;\n    const collapse = () => setupCollapse(bodyEl, settings, {\n      expanded: block.ui.expanded.has(index),\n      onToggle: (open) => (open ? block.ui.expanded.add(index) : block.ui.expanded.delete(index)),\n    });\n    if (onlyLink) {\n      // в тексте только [[ссылка]] — вместо неё несколько строк из заметки и «Читать далее»;\n      // если у заметки нет текста, показываем саму ссылку\n      appendLinkedText(bodyEl, ev.linkedNotes.slice(0, 3), ctx).then((shown) => {\n        if (!shown) renderMarkdown(app, text, bodyEl, sourcePath, component);\n      });\n    } else {\n      // собственный текст события показывается как есть (сворачивание — только если включено в настройках)\n      renderMarkdown(app, text, bodyEl, sourcePath, component).then(collapse);\n    }\n    // текст — всегда предпросмотр; правка по двойному клику, карандашу или из меню\n    bodyEl.addEventListener('dblclick', (e) => {\n      if (e.target.closest('a, .tc-toggle, img, video, audio, input, .callout-fold, .internal-embed')) return;\n      if (window.getSelection) window.getSelection().removeAllRanges();\n      editBody();\n    });\n  };\n  const editBody = () => openInlineTextarea(bodyWrap, {\n    value: ev.body, app, sourcePath, component,\n    onSave: (v) => block.mutate((c) => { c.entries[index].body = v; }),\n    onCancel: showBody,\n  });\n  showBody();\n\n  /* --- медиа --- */\n  const own = new Set(items.map((i) => i.file.path));\n  const linkedMedia = (ev.linkedMedia || []).filter((m) => !own.has(m.file.path));\n  renderMediaSection(card, items.concat(linkedMedia), { app, settings, sourcePath });\n\n  /* --- низ: теги, ID и кнопки (кнопки внизу, чтобы не сдвигать дату в шапке) --- */\n  const foot = card.createDiv({ cls: 'tc-event-foot' });\n  const linked = ev.linkedTags || [];\n  if (!ev.tags.length && !linked.length && !(settings.showIds && ev.id)) foot.addClass('is-bare');\n  const tags = foot.createDiv({ cls: 'tc-tags' });\n  ev.tags.forEach((t) => tagPill(tags, t, (tag) => block.setQuery(`#${tag}`)));\n  linked.forEach(({ tag, from }) => {\n    const pill = tagPill(tags, tag, (t) => block.setQuery(`#${t}`));\n    pill.addClass('is-linked');\n    pill.setAttr('aria-label', `Из заметки: ${from.join(', ')}`);\n  });\n  if (settings.showIds && ev.id) foot.createDiv({ cls: 'tc-event-id', text: `ID: #${ev.id}` });\n  const actions = foot.createDiv({ cls: 'tc-event-actions' });\n  const editBtn = actions.createDiv({ cls: 'tc-icon-btn', attr: { 'aria-label': 'Редактировать в форме' } });\n  setIcon(editBtn, 'pencil');\n  editBtn.addEventListener('click', (e) => { e.stopPropagation(); block.openForm(ev, index); });\n  const moreBtn = actions.createDiv({ cls: 'tc-icon-btn', attr: { 'aria-label': 'Действия' } });\n  setIcon(moreBtn, 'more-horizontal');\n  const showMenu = (e) => {\n    e.preventDefault();\n    e.stopPropagation();\n    eventMenu(ev, index, ctx, editBody).showAtMouseEvent(e);\n  };\n  moreBtn.addEventListener('click', showMenu);\n  card.addEventListener('contextmenu', (e) => {\n    if (e.target.closest('textarea, input')) return;\n    showMenu(e);\n  });\n  return row;\n}\n\n/**\n * «Кат» с фрагментом связанной заметки. Текст читается и рисуется только\n * при первом раскрытии, ссылки внутри работают относительно самой заметки.\n */\n/**\n * Текст связанных заметок прямо в теле карточки (без свойств, медиа и\n * заголовка с именем заметки). Ссылки внутри работают относительно самой заметки.\n */\nasync function appendLinkedText(bodyEl, files, ctx) {\n  const { app, settings } = ctx;\n  const lines = Math.max(1, settings.excerptLines || 4);\n  let shown = 0;\n  for (const file of files) {\n    try {\n      const ex = await noteExcerpt(app, file, settings.excerptLength || 1200);\n      if (!markdownToPlain(ex.text)) continue;\n      const box = bodyEl.createDiv({ cls: 'tc-linked-text' });\n      shown++;\n      const clip = box.createDiv({ cls: 'tc-linked-clip' });\n      // только текст, без разметки; переносы строк сохраняются (white-space: pre-line)\n      clip.setText(markdownToPlain(ex.text));\n      const more = box.createDiv({ cls: 'tc-linked-more', text: 'Читать далее →' });\n      more.addEventListener('click', (e) => {\n        e.stopPropagation();\n        app.workspace.openLinkText(file.path, ctx.sourcePath, e.ctrlKey || e.metaKey || 'tab');\n      });\n      // обрезка ровно по N строкам: высоту считаем от line-height после раскладки\n      requestAnimationFrame(() => {\n        if (!clip.isConnected) return;\n        const cs = window.getComputedStyle(clip);\n        let lh = parseFloat(cs.lineHeight);\n        if (!lh || isNaN(lh)) lh = (parseFloat(cs.fontSize) || 15) * 1.6;\n        const max = Math.round(lh * lines);\n        const overflow = clip.scrollHeight > max + 2;\n        if (overflow) {\n          clip.style.maxHeight = `${max}px`;\n          clip.addClass('is-clipped');\n        }\n        if (!overflow && !ex.truncated) more.remove();\n      });\n    } catch (err) {\n      console.warn('[Event Timeline] не удалось прочитать', file.path, err);\n    }\n  }\n  return shown;\n}\n\nfunction eventMenu(ev, index, ctx, editBody) {\n  const { app, block, sourcePath } = ctx;\n  const menu = new Menu();\n  menu.addItem((it) => it.setTitle('Редактировать в форме').setIcon('pencil').onClick(() => block.openForm(ev, index)));\n  menu.addItem((it) => it.setTitle('Изменить текст на месте').setIcon('text-cursor-input').onClick(() => editBody()));\n  menu.addItem((it) => it.setTitle(ev.breakText != null ? 'Убрать разрыв линии' : 'Разрыв линии перед событием')\n    .setIcon('unfold-horizontal')\n    .onClick(() => block.mutate((c) => { c.entries[index].breakText = ev.breakText != null ? null : ''; })));\n  menu.addSeparator();\n  menu.addItem((it) => it.setTitle('Переместить выше').setIcon('arrow-up').onClick(() => block.move(index, -1)));\n  menu.addItem((it) => it.setTitle('Переместить ниже').setIcon('arrow-down').onClick(() => block.move(index, 1)));\n  menu.addItem((it) => it.setTitle('Дублировать').setIcon('copy').onClick(() => block.mutate((c) => {\n    const copy = { ...c.entries[index], tags: [...c.entries[index].tags], title: `${c.entries[index].title} (копия)` };\n    c.entries.splice(index + 1, 0, copy);\n  })));\n  menu.addItem((it) => it.setTitle('Скопировать ссылку на заметку').setIcon('link').onClick(async () => {\n    const file = app.vault.getAbstractFileByPath(sourcePath);\n    const link = file ? app.fileManager.generateMarkdownLink(file, '') : sourcePath;\n    await navigator.clipboard.writeText(`${link} — ${ev.title}`);\n    new Notice('Ссылка скопирована');\n  }));\n  menu.addSeparator();\n  menu.addItem((it) => {\n    it.setTitle('Удалить событие').setIcon('trash-2').onClick(async () => {\n      const ok = await confirm(app, { title: 'Удалить событие?', message: `«${ev.title}» будет удалено из таймлайна.` });\n      if (ok) block.mutate((c) => { c.entries.splice(index, 1); });\n    });\n    if (it.setWarning) it.setWarning(true);\n  });\n  return menu;\n}\n\nmodule.exports = { renderEventCard, renderBullet, tagPill, renderMarkdown };\n","render/eventForm":"'use strict';\n\n/*\n * Форма «Добавить событие в таймлайн» (по макету). Та же форма используется\n * для редактирования: open(event, index) заполняет поля и меняет подписи.\n */\n\nconst { setIcon, Notice, TFile } = require('obsidian');\nconst { MARKERS, MARKER_ORDER } = require('../constants');\nconst { parseTags } = require('../utils/text');\nconst { autoResize } = require('../utils/dom');\nconst { attachLinkSuggest } = require('./linkSuggest');\nconst { createMdTabs, attachPreview } = require('./inlineEdit');\nconst { extractMedia, kindOf } = require('./media');\nconst { VaultFileModal } = require('../modals/VaultFileModal');\n\nfunction autoDateString(settings) {\n  if (!settings.autoDate) return '';\n  const m = window.moment;\n  if (typeof m === 'function') {\n    try { return m().locale(settings.dateLocale || 'ru').format(settings.dateFormat || 'YYYY-MM-DD HH:mm'); } catch (e) { /* ниже */ }\n  }\n  const d = new Date();\n  const p = (n) => String(n).padStart(2, '0');\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;\n}\n\nfunction field(parent, label, hint) {\n  const wrap = parent.createDiv({ cls: 'tc-field' });\n  const lab = wrap.createDiv({ cls: 'tc-field-label' });\n  lab.createSpan({ text: label });\n  if (hint) lab.createSpan({ cls: 'tc-field-hint', text: hint });\n  return wrap;\n}\n\n/**\n * @param parent  контейнер\n * @param ctx     { app, settings, sourcePath }\n * @param opts    { onSubmit(eventData, index|null): Promise, collapsed: bool }\n */\nfunction createEventForm(parent, ctx, opts) {\n  const { app, settings, sourcePath } = ctx;\n  const state = { index: null, marker: 'empty', attachments: [], breakOn: false };\n\n  const root = parent.createDiv({ cls: 'tc-form' });\n  root.toggleClass('is-collapsed', !!opts.collapsed);\n\n  /* ---- шапка ---- */\n  const head = root.createDiv({ cls: 'tc-form-head' });\n  const plus = head.createDiv({ cls: 'tc-form-plus' });\n  setIcon(plus, 'plus');\n  const headTitle = head.createDiv({ cls: 'tc-form-title', text: 'Добавить событие в таймлайн' });\n  head.createEl('kbd', { cls: 'tc-kbd', text: 'Alt + N' });\n  head.createDiv({ cls: 'tc-spacer' });\n  const modeChip = head.createDiv({ cls: 'tc-chip', text: 'форма создания' });\n  const chevron = head.createDiv({ cls: 'tc-form-chevron' });\n  setIcon(chevron, 'chevron-down');\n  head.addEventListener('click', () => (root.hasClass('is-collapsed') ? open() : collapse()));\n\n  const body = root.createDiv({ cls: 'tc-form-body' });\n\n  /* ---- заголовок + дата ---- */\n  const row1 = body.createDiv({ cls: 'tc-form-row tc-row-title' });\n  const titleInput = field(row1, 'Заголовок события *').createEl('input', {\n    cls: 'tc-input', attr: { type: 'text', placeholder: 'Например: Саммит БРИКС или Подписание соглашения…' },\n  });\n  const dateInput = field(row1, 'Дата / период *').createEl('input', {\n    cls: 'tc-input tc-mono', attr: { type: 'text', placeholder: '12 мая 2026 или Май 2026' },\n  });\n\n  /* ---- тип буллета + разрыв ---- */\n  const row2 = body.createDiv({ cls: 'tc-form-row tc-row-marker' });\n  const markerWrap = field(row2, 'Тип буллета (timeline marker)').createDiv({ cls: 'tc-marker-picker' });\n  const markerBtns = {};\n  for (const key of MARKER_ORDER) {\n    const m = MARKERS[key];\n    const btn = markerWrap.createDiv({ cls: `tc-marker-option is-${key}`, attr: { 'aria-label': m.label } });\n    const icon = btn.createDiv({ cls: `tc-bullet is-${key}` });\n    if (m.icon) setIcon(icon, m.icon);\n    btn.createDiv({ cls: 'tc-marker-option-label', text: m.label });\n    btn.addEventListener('click', () => setMarker(key));\n    markerBtns[key] = btn;\n  }\n\n  const breakField = field(row2, 'Разрыв временной линии');\n  const breakCard = breakField.createDiv({ cls: 'tc-break-card' });\n  const breakIcon = breakCard.createDiv({ cls: 'tc-break-icon' });\n  setIcon(breakIcon, 'unfold-horizontal');\n  const breakInfo = breakCard.createDiv({ cls: 'tc-break-info' });\n  breakInfo.createDiv({ cls: 'tc-break-title', text: 'Разрыв линии перед событием' });\n  breakInfo.createDiv({ cls: 'tc-break-desc', text: 'Индикатор паузы между событиями' });\n  const toggle = breakCard.createDiv({ cls: 'checkbox-container' });\n  toggle.createEl('input', { attr: { type: 'checkbox', tabindex: '-1' } });\n  const breakText = breakField.createEl('input', {\n    cls: 'tc-input tc-break-text', attr: { type: 'text', placeholder: 'Подпись разрыва, например: Период консультаций' },\n  });\n  breakCard.addEventListener('click', () => setBreak(!state.breakOn));\n\n  /* ---- текст ---- */\n  const textField = field(body, 'Текст заметки (Markdown и [[wiki-ссылки]])', 'Поддерживается [[Wiki-link]]');\n  const mdTabs = createMdTabs(textField);\n  const textarea = textField.createEl('textarea', {\n    cls: 'tc-input tc-textarea',\n    attr: { rows: '4', placeholder: 'Краткое описание события… Используйте [[Имя страницы]] для связи с заметками.' },\n  });\n  textarea.addEventListener('input', () => autoResize(textarea));\n  const suggest = attachLinkSuggest(textarea, app, sourcePath);\n  const preview = attachPreview(textField, textarea, mdTabs, { app, sourcePath, component: ctx.component });\n\n  /* ---- метка, id ---- */\n  const row3 = body.createDiv({ cls: 'tc-form-row tc-row-meta' });\n  const labelInput = field(row3, 'Метка на карточке').createEl('input', {\n    cls: 'tc-input', attr: { type: 'text', placeholder: 'Тревога / Финансы' },\n  });\n  const idInput = field(row3, 'ID').createEl('input', {\n    cls: 'tc-input tc-mono', attr: { type: 'text', placeholder: 'fin-2026-02' },\n  });\n\n  /* ---- медиа ---- */\n  const drop = body.createDiv({ cls: 'tc-dropzone' });\n  const dropText = drop.createDiv({ cls: 'tc-dropzone-text' });\n  setIcon(dropText.createSpan({ cls: 'tc-dropzone-icon' }), 'image');\n  dropText.createSpan({ text: 'Прикрепить медиафайлы (изображения, видео, документы) — кнопкой или перетаскиванием' });\n  const dropBtns = drop.createDiv({ cls: 'tc-dropzone-btns' });\n  const fileInput = drop.createEl('input', { attr: { type: 'file', multiple: '' } });\n  fileInput.style.display = 'none';\n  const pickBtn = (icon, text, handler) => {\n    const b = dropBtns.createEl('button', { cls: 'tc-btn tc-btn-ghost' });\n    setIcon(b.createSpan({ cls: 'tc-btn-icon' }), icon);\n    b.createSpan({ text });\n    b.addEventListener('click', (e) => { e.preventDefault(); handler(); });\n  };\n  const pickLocal = (accept) => { fileInput.accept = accept; fileInput.value = ''; fileInput.click(); };\n  pickBtn('video', 'Видео', () => pickLocal('video/*'));\n  pickBtn('image', 'Фото', () => pickLocal('image/*'));\n  pickBtn('paperclip', 'Файл', () => pickLocal(''));\n  pickBtn('vault', 'Из хранилища', () => new VaultFileModal(app, (f) => addAttachment(f)).open());\n  const chips = body.createDiv({ cls: 'tc-attach-chips' });\n\n  fileInput.addEventListener('change', () => importFiles(Array.from(fileInput.files || [])));\n  drop.addEventListener('dragover', (e) => { e.preventDefault(); drop.addClass('is-over'); });\n  drop.addEventListener('dragleave', () => drop.removeClass('is-over'));\n  drop.addEventListener('drop', (e) => {\n    e.preventDefault();\n    drop.removeClass('is-over');\n    const files = Array.from((e.dataTransfer && e.dataTransfer.files) || []);\n    if (files.length) { importFiles(files); return; }\n    // перетаскивание из файлового проводника Obsidian\n    const text = e.dataTransfer && e.dataTransfer.getData('text/plain');\n    const m = text && text.match(/\\[\\[([^\\]]+)\\]\\]/);\n    const f = m && app.metadataCache.getFirstLinkpathDest(m[1], sourcePath);\n    if (f instanceof TFile) addAttachment(f);\n  });\n\n  /* ---- низ ---- */\n  const foot = body.createDiv({ cls: 'tc-form-foot' });\n  foot.createSpan({ cls: 'tc-field-label tc-inline-label', text: 'Теги:' });\n  const tagsInput = foot.createEl('input', { cls: 'tc-input tc-mono tc-tags-input', attr: { type: 'text', placeholder: '#геополитика, #хроника' } });\n  foot.createDiv({ cls: 'tc-spacer' });\n  const cancelBtn = foot.createEl('button', { cls: 'tc-btn', text: 'Отмена' });\n  const submitBtn = foot.createEl('button', { cls: 'tc-btn tc-btn-primary' });\n  setIcon(submitBtn.createSpan({ cls: 'tc-btn-icon' }), 'check');\n  const submitLabel = submitBtn.createSpan({ text: 'Добавить в таймлайн' });\n\n  cancelBtn.addEventListener('click', (e) => { e.preventDefault(); reset(); collapse(); });\n  submitBtn.addEventListener('click', (e) => { e.preventDefault(); submit(); });\n  root.addEventListener('keydown', (e) => {\n    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); submit(); }\n    else if (e.key === 'Escape' && !suggest.isOpen()) { e.preventDefault(); reset(); collapse(); }\n  });\n\n  /* ---- логика ---- */\n  function setMarker(key) {\n    state.marker = key;\n    for (const k of MARKER_ORDER) markerBtns[k].toggleClass('is-selected', k === key);\n  }\n  function setBreak(on) {\n    state.breakOn = on;\n    toggle.toggleClass('is-enabled', on);\n    breakText.toggleClass('is-hidden', !on);\n  }\n  function renderChips() {\n    chips.empty();\n    state.attachments.forEach((link, i) => {\n      const chip = chips.createDiv({ cls: 'tc-attach-chip' });\n      const ext = link.split('.').pop();\n      const kind = kindOf(ext);\n      setIcon(chip.createSpan({ cls: 'tc-attach-icon' }), kind === 'image' ? 'image' : kind === 'video' ? 'video' : kind === 'audio' ? 'music' : 'file');\n      chip.createSpan({ text: link.split('/').pop() });\n      const x = chip.createSpan({ cls: 'tc-attach-remove' });\n      setIcon(x, 'x');\n      x.addEventListener('click', () => { state.attachments.splice(i, 1); renderChips(); });\n    });\n  }\n  function addAttachment(file) {\n    const link = app.metadataCache.fileToLinktext(file, sourcePath, false);\n    if (!state.attachments.includes(link)) state.attachments.push(link);\n    renderChips();\n  }\n  async function importFiles(files) {\n    for (const f of files) {\n      try {\n        const buf = await f.arrayBuffer();\n        const path = await app.fileManager.getAvailablePathForAttachment(f.name, sourcePath);\n        const created = await app.vault.createBinary(path, buf);\n        addAttachment(created);\n      } catch (err) {\n        console.error('[Event Timeline] не удалось сохранить вложение', err);\n        new Notice(`Не удалось сохранить ${f.name}: ${err.message}`);\n      }\n    }\n  }\n\n  function reset() {\n    state.index = null;\n    state.attachments = [];\n    titleInput.value = '';\n    dateInput.value = autoDateString(settings);\n    textarea.value = '';\n    labelInput.value = '';\n    idInput.value = '';\n    tagsInput.value = '';\n    breakText.value = '';\n    setMarker('empty');\n    setBreak(false);\n    renderChips();\n    headTitle.setText('Добавить событие в таймлайн');\n    modeChip.setText('форма создания');\n    submitLabel.setText('Добавить в таймлайн');\n    root.removeClass('is-editing');\n    if (preview.isActive()) preview.show(false);\n    autoResize(textarea);\n  }\n\n  function fill(ev, index) {\n    reset();\n    state.index = index;\n    const { text, items } = extractMedia(ev.body, app, sourcePath);\n    titleInput.value = ev.title || '';\n    dateInput.value = ev.date || '';\n    textarea.value = text;\n    labelInput.value = ev.label || '';\n    idInput.value = ev.id || '';\n    tagsInput.value = (ev.tags || []).map((t) => '#' + t).join(', ');\n    breakText.value = ev.breakText || '';\n    state.attachments = items.map((i) => i.link);\n    setMarker(ev.marker || 'empty');\n    setBreak(ev.breakText != null);\n    renderChips();\n    headTitle.setText('Редактирование события');\n    modeChip.setText('правка');\n    submitLabel.setText('Сохранить изменения');\n    root.addClass('is-editing');\n    setTimeout(() => autoResize(textarea), 0);\n  }\n\n  async function submit() {\n    const title = titleInput.value.trim();\n    const date = dateInput.value.trim();\n    if (!title) { titleInput.addClass('is-invalid'); titleInput.focus(); return; }\n    if (!date) { dateInput.addClass('is-invalid'); dateInput.focus(); return; }\n    titleInput.removeClass('is-invalid');\n    dateInput.removeClass('is-invalid');\n    const media = state.attachments.map((l) => `![[${l}]]`).join('\\n');\n    const text = textarea.value.replace(/\\s+$/, '');\n    const eventData = {\n      type: 'event',\n      title,\n      date,\n      marker: state.marker,\n      label: labelInput.value.trim(),\n      tags: parseTags(tagsInput.value),\n      id: idInput.value.trim(),\n      breakText: state.breakOn ? breakText.value.trim() : null,\n      body: [text, media].filter(Boolean).join('\\n\\n'),\n    };\n    submitBtn.disabled = true;\n    try {\n      await opts.onSubmit(eventData, state.index);\n      reset();\n      collapse();\n    } catch (err) {\n      console.warn('[Event Timeline] событие не сохранено', err);\n    } finally {\n      submitBtn.disabled = false;\n    }\n  }\n\n  function open(ev, index) {\n    if (ev) fill(ev, index);\n    else if (root.hasClass('is-editing')) reset();\n    else if (!dateInput.value) dateInput.value = autoDateString(settings);\n    root.removeClass('is-collapsed');\n    root.scrollIntoView({ block: 'nearest', behavior: 'smooth' });\n    setTimeout(() => titleInput.focus(), 50);\n  }\n  function collapse() {\n    root.addClass('is-collapsed');\n  }\n\n  reset();\n  return { el: root, open, collapse, reset, isDirty: () => !!(titleInput.value || textarea.value) };\n}\n\nmodule.exports = { createEventForm, autoDateString };\n","render/graph":"'use strict';\n\n/*\n * Граф связей: события и заметки, на которые они ссылаются.\n * Простая детерминированная силовая раскладка без внешних библиотек.\n */\n\nconst SVG_NS = 'http://www.w3.org/2000/svg';\n\nfunction svg(tag, attrs, parent) {\n  const el = document.createElementNS(SVG_NS, tag);\n  for (const [k, v] of Object.entries(attrs || {})) el.setAttribute(k, String(v));\n  if (parent) parent.appendChild(el);\n  return el;\n}\n\nfunction layout(nodes, edges, { width, height, iterations = 300, padX = 90, padY = 30 }) {\n  const byId = new Map(nodes.map((n) => [n.id, n]));\n  const cx = width / 2;\n  const cy = height / 2;\n  // детерминированная стартовая раскладка по спирали\n  nodes.forEach((n, i) => {\n    const a = i * 2.39996;\n    const r = 18 * Math.sqrt(i + 1);\n    n.x = cx + r * Math.cos(a) * (width / height);\n    n.y = cy + r * Math.sin(a);\n  });\n  const area = (width - 2 * padX) * (height - 2 * padY);\n  const k = Math.sqrt(area / Math.max(1, nodes.length)) * 0.9;\n  let temp = width / 8;\n  for (let it = 0; it < iterations; it++) {\n    for (const n of nodes) { n.dx = 0; n.dy = 0; }\n    for (let i = 0; i < nodes.length; i++) {\n      for (let j = i + 1; j < nodes.length; j++) {\n        const a = nodes[i]; const b = nodes[j];\n        const dx = a.x - b.x; const dy = a.y - b.y;\n        const d = Math.max(0.01, Math.hypot(dx, dy));\n        const f = (k * k) / d;\n        a.dx += (dx / d) * f; a.dy += (dy / d) * f;\n        b.dx -= (dx / d) * f; b.dy -= (dy / d) * f;\n      }\n    }\n    for (const e of edges) {\n      const a = byId.get(e.from); const b = byId.get(e.to);\n      if (!a || !b) continue;\n      const dx = a.x - b.x; const dy = a.y - b.y;\n      const d = Math.max(0.01, Math.hypot(dx, dy));\n      const f = ((d * d) / k) * (e.weak ? 0.35 : 1);\n      a.dx -= (dx / d) * f; a.dy -= (dy / d) * f;\n      b.dx += (dx / d) * f; b.dy += (dy / d) * f;\n    }\n    for (const n of nodes) {\n      // гравитация к центру держит несвязанные части вместе\n      n.dx += (cx - n.x) * 0.08 * (k / 40);\n      n.dy += (cy - n.y) * 0.08 * (k / 40) * (width / height);\n      const d = Math.max(0.01, Math.hypot(n.dx, n.dy));\n      const step = Math.min(d, temp);\n      n.x = Math.max(padX, Math.min(width - padX, n.x + (n.dx / d) * step));\n      n.y = Math.max(padY, Math.min(height - padY, n.y + (n.dy / d) * step));\n    }\n    temp = Math.max(0.5, temp * 0.97);\n  }\n}\n\n/**\n * @param parent\n * @param graph   { nodes, edges } из stats.buildGraph\n * @param opts    { height, compact, onEvent(node), onPage(node), resolved(label)->bool }\n */\nfunction renderGraph(parent, graph, opts = {}) {\n  const width = opts.width || 640;\n  const height = opts.height || 420;\n  const nodes = graph.nodes.map((n) => ({ ...n }));\n  const edges = graph.edges;\n  const wrap = parent.createDiv({ cls: `tc-graph${opts.compact ? ' is-compact' : ''}` });\n  if (!nodes.length) {\n    wrap.createDiv({ cls: 'tc-graph-empty', text: 'Нет связей: добавьте [[ссылки]] в текст событий' });\n    return wrap;\n  }\n  layout(nodes, edges, { width, height, iterations: opts.compact ? 160 : 320, padX: opts.compact ? 14 : 90, padY: opts.compact ? 14 : 30 });\n  const root = svg('svg', { viewBox: `0 0 ${width} ${height}`, class: 'tc-graph-svg', preserveAspectRatio: 'xMidYMid meet' });\n  wrap.appendChild(root);\n  const byId = new Map(nodes.map((n) => [n.id, n]));\n  const gEdges = svg('g', { class: 'tc-graph-edges' }, root);\n  const edgeEls = edges.map((e) => {\n    const a = byId.get(e.from); const b = byId.get(e.to);\n    return { e, el: svg('line', { x1: a.x, y1: a.y, x2: b.x, y2: b.y, class: e.weak ? 'is-seq' : '' }, gEdges) };\n  });\n  const gNodes = svg('g', { class: 'tc-graph-nodes' }, root);\n  for (const n of nodes) {\n    const kindCls = n.kind === 'page' ? `is-page${opts.resolved && !opts.resolved(n.label) ? ' is-unresolved' : ''}` : `is-${n.kind} is-${n.marker || 'empty'}`;\n    const g = svg('g', { class: `tc-graph-node ${kindCls}`, transform: `translate(${n.x},${n.y})` }, gNodes);\n    const r = n.kind === 'center' ? 9 : n.kind === 'page' ? 5 + Math.min(6, (n.degree || 1)) : 6;\n    svg('circle', { r }, g);\n    if (!opts.compact) {\n      const label = n.label.length > 28 ? `${n.label.slice(0, 27)}…` : n.label;\n      const t = svg('text', { y: r + 13, 'text-anchor': 'middle' }, g);\n      t.textContent = label;\n    }\n    const title = svg('title', {}, g);\n    title.textContent = n.label;\n    g.addEventListener('mouseenter', () => {\n      wrap.addClass('is-hovering');\n      g.classList.add('is-hover');\n      edgeEls.forEach(({ e, el }) => { if (e.from === n.id || e.to === n.id) el.classList.add('is-hover'); });\n    });\n    g.addEventListener('mouseleave', () => {\n      wrap.removeClass('is-hovering');\n      g.classList.remove('is-hover');\n      edgeEls.forEach(({ el }) => el.classList.remove('is-hover'));\n    });\n    g.addEventListener('click', (ev) => {\n      if (n.kind === 'page' && opts.onPage) opts.onPage(n, ev);\n      else if (n.kind === 'event' && opts.onEvent) opts.onEvent(n, ev);\n    });\n  }\n  return wrap;\n}\n\nmodule.exports = { renderGraph };\n","render/header":"'use strict';\n\n/* Шапка карточки: режимы, теги, заголовок, бейдж, поиск, кнопка «Запись», описание. */\n\nconst { setIcon } = require('obsidian');\nconst { THEME_PRESETS } = require('../constants');\nconst { resolveAccent, openPopover } = require('../utils/dom');\nconst { debounce } = require('../utils/text');\nconst { makeInlineInput } = require('./inlineEdit');\nconst { tagPill, renderMarkdown } = require('./eventCard');\n\nconst MODES = [\n  { key: 'timeline', label: 'Таймлайн', icon: 'list' },\n  { key: 'source', label: 'Исходный код', icon: 'code' },\n  { key: 'graph', label: 'Граф', icon: 'share-2' },\n];\n\nfunction renderColorPicker(parent, card, ctx) {\n  const { settings, block } = ctx;\n  const swatch = parent.createDiv({ cls: 'tc-color-swatch', attr: { 'aria-label': 'Цвет карточки' } });\n  swatch.style.background = resolveAccent(card.color, settings);\n  swatch.addEventListener('click', (e) => {\n    e.stopPropagation();\n    openPopover(swatch, (pop, close) => {\n      const grid = pop.createDiv({ cls: 'tc-color-grid' });\n      for (const [key, preset] of Object.entries(THEME_PRESETS)) {\n        const opt = grid.createDiv({ cls: 'tc-color-option', attr: { 'aria-label': preset.label } });\n        opt.style.background = preset.color;\n        if (card.color === key) opt.addClass('is-active');\n        opt.addEventListener('click', () => { close(); block.mutate((c) => { c.color = key; }); });\n      }\n      const custom = grid.createEl('label', { cls: 'tc-color-option tc-color-custom', attr: { 'aria-label': 'Свой цвет' }, text: '⋯' });\n      const input = custom.createEl('input', { attr: { type: 'color' } });\n      input.value = resolveAccent(card.color, settings);\n      input.addEventListener('change', () => { close(); block.mutate((c) => { c.color = input.value; }); });\n      const reset = pop.createDiv({ cls: 'tc-color-reset', text: 'Сбросить (тема по умолчанию)' });\n      reset.addEventListener('click', () => { close(); block.mutate((c) => { c.color = ''; }); });\n    }, 'tc-color-popover');\n  });\n}\n\nfunction renderHeader(parent, card, ctx) {\n  const { app, settings, sourcePath, component, block } = ctx;\n  const head = parent.createDiv({ cls: 'tc-header' });\n\n  /* --- верхняя полоса: теги слева, режимы справа --- */\n  const top = head.createDiv({ cls: 'tc-header-top' });\n  const tags = top.createDiv({ cls: 'tc-tags tc-header-tags' });\n  card.tags.forEach((t) => tagPill(tags, t, (tag) => block.setQuery(`#${tag}`)));\n  top.createDiv({ cls: 'tc-spacer' });\n  const modes = top.createDiv({ cls: 'tc-modes' });\n  for (const m of MODES) {\n    const btn = modes.createDiv({ cls: `tc-mode${block.ui.mode === m.key ? ' is-active' : ''}` });\n    setIcon(btn.createSpan({ cls: 'tc-mode-icon' }), m.icon);\n    btn.createSpan({ cls: 'tc-mode-label', text: m.label });\n    btn.addEventListener('click', () => block.setMode(m.key));\n  }\n  renderColorPicker(top, card, ctx);\n\n  /* --- заголовок + поиск --- */\n  const row = head.createDiv({ cls: 'tc-header-main' });\n  const left = row.createDiv({ cls: 'tc-header-left' });\n  const titleLine = left.createDiv({ cls: 'tc-title-line' });\n  const title = titleLine.createDiv({ cls: `tc-card-title${card.title ? '' : ' is-placeholder'}`, text: card.title || 'Заголовок таймлайна' });\n  makeInlineInput(title, { value: card.title, onSave: (v) => block.mutate((c) => { c.title = v; }) });\n  if (card.badge) titleLine.createSpan({ cls: 'tc-card-badge', text: card.badge });\n\n  if (card.description) {\n    const desc = left.createDiv({ cls: 'tc-card-desc markdown-rendered' });\n    renderMarkdown(app, card.description, desc, sourcePath, component);\n  }\n\n  if (block.ui.mode === 'timeline') {\n    const tools = row.createDiv({ cls: 'tc-header-tools' });\n    if (settings.showSearch) {\n      const search = tools.createDiv({ cls: 'tc-search' });\n      setIcon(search.createSpan({ cls: 'tc-search-icon' }), 'search');\n      const input = search.createEl('input', { attr: { type: 'search', placeholder: 'Поиск по событиям…' } });\n      input.value = block.ui.query;\n      const apply = debounce(() => block.setQuery(input.value, true), 200);\n      input.addEventListener('input', apply);\n      input.addEventListener('keydown', (e) => { if (e.key === 'Escape') { input.value = ''; block.setQuery('', true); } });\n      block.searchInput = input;\n    }\n    const add = tools.createEl('button', { cls: 'tc-btn tc-btn-primary tc-add-btn' });\n    setIcon(add.createSpan({ cls: 'tc-btn-icon' }), 'plus');\n    add.createSpan({ text: 'Запись' });\n    add.addEventListener('click', () => block.openForm());\n  }\n  head.createDiv({ cls: 'tc-divider' });\n  return head;\n}\n\nmodule.exports = { renderHeader };\n","render/inlineEdit":"'use strict';\n\n/* Быстрая правка прямо в карточке (как в v2): клик по полю -> input/textarea. */\n\nconst { autoResize } = require('../utils/dom');\nconst { attachLinkSuggest } = require('./linkSuggest');\n\n/** Однострочное поле. onSave(value) вызывается только если значение изменилось. */\nfunction makeInlineInput(el, { value, onSave, cls = '' }) {\n  el.addClass('tc-editable');\n  el.addEventListener('click', (e) => {\n    if (e.target.closest('a')) return;\n    e.stopPropagation();\n    const input = createEl('input', { cls: `tc-inline-input ${cls}`, attr: { type: 'text' } });\n    input.value = value || '';\n    el.replaceWith(input);\n    input.focus();\n    input.select();\n    let done = false;\n    const finish = (save) => {\n      if (done) return;\n      done = true;\n      const v = input.value.trim();\n      if (save && v !== (value || '').trim()) onSave(v);\n      else input.replaceWith(el);\n    };\n    input.addEventListener('blur', () => finish(true));\n    input.addEventListener('keydown', (ev) => {\n      if (ev.key === 'Enter') { ev.preventDefault(); input.blur(); }\n      else if (ev.key === 'Escape') { ev.preventDefault(); finish(false); }\n    });\n  });\n}\n\n/** Многострочная правка текста события. Esc — отмена, Cmd/Ctrl+Enter или уход фокуса — сохранить. */\nfunction openInlineTextarea(container, { value, app, sourcePath, component, onSave, onCancel }) {\n  container.empty();\n  const tabs = createMdTabs(container);\n  const ta = container.createEl('textarea', { cls: 'tc-inline-textarea' });\n  ta.value = value || '';\n  const preview = attachPreview(container, ta, tabs, { app, sourcePath, component });\n  const suggest = attachLinkSuggest(ta, app, sourcePath);\n  const hint = container.createDiv({ cls: 'tc-inline-hint', text: 'Cmd/Ctrl+Enter — сохранить · Esc — отмена · [[ — ссылка' });\n  const bar = container.createDiv({ cls: 'tc-inline-bar' });\n  bar.appendChild(hint);\n  bar.createDiv({ cls: 'tc-spacer' });\n  const cancelBtn = bar.createEl('button', { cls: 'tc-btn', text: 'Отмена' });\n  const saveBtn = bar.createEl('button', { cls: 'tc-btn tc-btn-primary', text: 'Сохранить' });\n  cancelBtn.addEventListener('mousedown', (e) => { e.preventDefault(); finish(false); });\n  saveBtn.addEventListener('mousedown', (e) => { e.preventDefault(); finish(true); });\n  setTimeout(() => { autoResize(ta); ta.focus(); }, 0);\n  ta.addEventListener('input', () => autoResize(ta));\n  let done = false;\n  const finish = (save) => {\n    if (done) return;\n    done = true;\n    if (save && ta.value !== value) onSave(ta.value.replace(/\\s+$/, ''));\n    else onCancel();\n  };\n  ta.addEventListener('keydown', (e) => {\n    if (e.key === 'Escape' && !suggest.isOpen()) { e.preventDefault(); finish(false); }\n    else if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); finish(true); }\n  });\n  ta.addEventListener('blur', () => setTimeout(() => {\n    // переключение на «Просмотр» или клик по вкладкам не сохраняет и не закрывает редактор\n    if (suggest.isOpen() || document.activeElement === ta || preview.isActive() || container.contains(document.activeElement)) return;\n    if (container.matches(':hover')) return;\n    finish(true);\n  }, 160));\n  return { el: ta, hint };\n}\n\n/* ---------- вкладки «Текст / Просмотр» для полей с markdown ---------- */\n\nfunction createMdTabs(parent) {\n  const tabs = parent.createDiv({ cls: 'tc-md-tabs' });\n  const write = tabs.createDiv({ cls: 'tc-md-tab is-active', text: 'Текст' });\n  const view = tabs.createDiv({ cls: 'tc-md-tab', text: 'Просмотр' });\n  return { el: tabs, write, view };\n}\n\n/**\n * Предпросмотр markdown под вкладкой «Просмотр»: рендерит текст textarea\n * штатным рендерером Obsidian (ссылки, выноски, списки, встраивания).\n */\nfunction attachPreview(parent, ta, tabs, { app, sourcePath, component }) {\n  const { MarkdownRenderer } = require('obsidian');\n  const box = createDiv({ cls: 'tc-md-preview tc-event-body markdown-rendered' });\n  ta.after(box);\n  box.style.display = 'none';\n  let active = false;\n  const show = async (on) => {\n    active = on;\n    tabs.write.toggleClass('is-active', !on);\n    tabs.view.toggleClass('is-active', on);\n    ta.style.display = on ? 'none' : '';\n    box.style.display = on ? '' : 'none';\n    if (on) {\n      box.empty();\n      const md = ta.value.trim() ? ta.value : '*Пусто*';\n      if (MarkdownRenderer.render) await MarkdownRenderer.render(app, md, box, sourcePath, component);\n      else await MarkdownRenderer.renderMarkdown(md, box, sourcePath, component);\n      box.style.minHeight = '';\n    } else {\n      ta.focus();\n    }\n  };\n  tabs.write.addEventListener('mousedown', (e) => { e.preventDefault(); show(false); });\n  tabs.view.addEventListener('mousedown', (e) => { e.preventDefault(); show(true); });\n  return { isActive: () => active, show, el: box };\n}\n\nmodule.exports = { makeInlineInput, openInlineTextarea, createMdTabs, attachPreview };\n","render/linkSuggest":"'use strict';\n\n/*\n * Автокомплит `[[` для textarea (своя реализация: у Obsidian нет публичного\n * suggester'а для произвольного поля). Заметка вставляется как [[Имя]],\n * медиафайл — как встраивание ![[файл.ext]].\n */\n\nconst { autoResize } = require('../utils/dom');\n\nfunction attachLinkSuggest(textarea, app, sourcePath) {\n  let dropdown = null;\n  let items = [];\n  let selected = 0;\n  let ctx = null;\n\n  const close = () => {\n    if (dropdown) dropdown.remove();\n    dropdown = null;\n  };\n\n  const queryContext = () => {\n    const pos = textarea.selectionStart;\n    const m = /\\[\\[([^\\][\\n]*)$/.exec(textarea.value.slice(0, pos));\n    return m ? { query: m[1], start: pos - m[1].length } : null;\n  };\n\n  const candidates = (query) => {\n    const q = query.toLowerCase().split('|')[0];\n    return app.vault.getFiles()\n      .map((f) => {\n        const base = f.basename.toLowerCase();\n        const path = f.path.toLowerCase();\n        let score = -1;\n        if (!q) score = f.extension === 'md' ? 1 : 0;\n        else if (base === q) score = 4;\n        else if (base.startsWith(q)) score = 3;\n        else if (base.includes(q)) score = 2;\n        else if (path.includes(q)) score = 1;\n        return { f, score };\n      })\n      .filter((x) => x.score >= 0)\n      .sort((a, b) => b.score - a.score || b.f.stat.mtime - a.f.stat.mtime)\n      .slice(0, 12)\n      .map((x) => x.f);\n  };\n\n  const choose = (file) => {\n    const isMedia = file.extension !== 'md';\n    const link = app.metadataCache.fileToLinktext(file, sourcePath, true);\n    const insert = isMedia ? `![[${link}]]` : `[[${link}]]`;\n    let before = textarea.value.slice(0, ctx.start - 2);\n    if (isMedia && before.endsWith('!')) before = before.slice(0, -1);\n    const after = textarea.value.slice(textarea.selectionStart).replace(/^\\]\\]/, '');\n    textarea.value = before + insert + after;\n    const caret = (before + insert).length;\n    textarea.setSelectionRange(caret, caret);\n    close();\n    autoResize(textarea);\n    textarea.focus();\n    textarea.dispatchEvent(new Event('input'));\n  };\n\n  const highlight = () => {\n    if (!dropdown) return;\n    Array.from(dropdown.children).forEach((el, i) => el.toggleClass('is-selected', i === selected));\n    const sel = dropdown.children[selected];\n    if (sel && sel.scrollIntoView) sel.scrollIntoView({ block: 'nearest' });\n  };\n\n  const open = () => {\n    close();\n    if (!items.length) return;\n    dropdown = document.body.createDiv({ cls: 'tc-suggest' });\n    items.forEach((file, i) => {\n      const row = dropdown.createDiv({ cls: 'tc-suggest-item' });\n      row.createSpan({ cls: 'tc-suggest-name', text: file.extension === 'md' ? file.basename : file.name });\n      if (file.parent && file.parent.path !== '/') row.createSpan({ cls: 'tc-suggest-path', text: file.parent.path });\n      row.addEventListener('mousedown', (e) => { e.preventDefault(); choose(file); });\n      row.addEventListener('mouseenter', () => { selected = i; highlight(); });\n    });\n    const r = textarea.getBoundingClientRect();\n    dropdown.style.left = `${r.left}px`;\n    dropdown.style.top = `${r.bottom + 4}px`;\n    dropdown.style.width = `${Math.max(240, Math.min(r.width, 420))}px`;\n    highlight();\n  };\n\n  textarea.addEventListener('input', () => {\n    const c = queryContext();\n    if (!c) { close(); return; }\n    ctx = c;\n    items = candidates(c.query);\n    selected = 0;\n    open();\n  });\n\n  textarea.addEventListener('keydown', (e) => {\n    if (!dropdown) return;\n    if (e.key === 'ArrowDown') { e.preventDefault(); selected = (selected + 1) % items.length; highlight(); }\n    else if (e.key === 'ArrowUp') { e.preventDefault(); selected = (selected - 1 + items.length) % items.length; highlight(); }\n    else if (e.key === 'Enter' || e.key === 'Tab') { e.preventDefault(); e.stopPropagation(); choose(items[selected]); }\n    else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(); }\n  });\n  textarea.addEventListener('blur', () => setTimeout(close, 150));\n\n  return { isOpen: () => !!dropdown, close };\n}\n\nmodule.exports = { attachLinkSuggest };\n","render/list":"'use strict';\n\n/*\n * Лента событий: группы (секции #### или годы), разрывы линии, поиск, сортировка.\n */\n\nconst { setIcon } = require('obsidian');\nconst { plural } = require('../utils/text');\nconst { monthLabel } = require('../utils/dates');\nconst { renderEventCard } = require('./eventCard');\nconst { allTags } = require('../model/linkedTags');\n\nconst RECORDS = ['ключевая запись', 'ключевые записи', 'ключевых записей'];\n\nfunction matches(ev, query) {\n  if (!query) return true;\n  const terms = query.toLowerCase().split(/\\s+/).filter(Boolean);\n  const hay = `${ev.title}\\n${ev.body}\\n${ev.label}\\n${ev.date}\\n${ev.id}`.toLowerCase();\n  return terms.every((t) => (t.startsWith('marker:') ? ev.marker === t.slice(7) : t.startsWith('#') && t.length > 1\n    ? allTags(ev).some((tag) => tag.toLowerCase().startsWith(t.slice(1)))\n    : hay.includes(t) || allTags(ev).some((tag) => tag.toLowerCase().includes(t))));\n}\n\n/**\n * Проставляет каждому событию «эффективные» ключ сортировки и год.\n * Событие с нераспознанной датой («Весной как-то») не улетает в конец и не\n * рвёт группу года: оно наследует позицию предыдущего события в заметке\n * (а если его нет — следующего).\n */\nfunction annotate(items) {\n  let lastKey = null;\n  let lastYear = null;\n  for (const it of items) {\n    const s = it.ev.dateSpec;\n    if (s && s.valid) { lastKey = s.sortKey; lastYear = s.year; }\n    it.key = s && s.valid ? s.sortKey : lastKey;\n    it.year = s && s.valid ? s.year : lastYear;\n  }\n  let nextKey = null;\n  let nextYear = null;\n  for (let i = items.length - 1; i >= 0; i--) {\n    const it = items[i];\n    if (it.key == null) { it.key = nextKey; it.year = nextYear; } else { nextKey = it.key; nextYear = it.year; }\n  }\n  return items;\n}\n\nfunction sortEvents(items, mode) {\n  annotate(items);\n  if (mode === 'file') return items;\n  return [...items].sort((a, b) => (a.key == null || b.key == null ? 0 : a.key - b.key) || a.index - b.index);\n}\n\n/** Делит события на группы: [{ label, kind: 'section'|'year'|'none', items: [{ev, index}] }] */\nfunction buildGroups(card, settings, sortMode) {\n  const hasSections = card.entries.some((e) => e.type === 'section');\n  let groups = [];\n  if (hasSections) {\n    let cur = { label: '', kind: 'none', items: [] };\n    card.entries.forEach((e, index) => {\n      if (e.type === 'section') {\n        if (cur.items.length || cur.label) groups.push(cur);\n        cur = { label: e.label, kind: 'section', items: [] };\n      } else cur.items.push({ ev: e, index });\n    });\n    groups.push(cur);\n    groups.forEach((g) => { g.items = sortEvents(g.items, sortMode); });\n  } else {\n    const all = sortEvents(card.entries.map((ev, index) => ({ ev, index })).filter((x) => x.ev.type === 'event'), sortMode);\n    if (!settings.groupByYear) groups = [{ label: '', kind: 'none', items: all }];\n    else {\n      for (const it of all) {\n        const label = it.year != null ? String(it.year) : 'Без даты';\n        const last = groups[groups.length - 1];\n        if (last && last.label === label) last.items.push(it);\n        else groups.push({ label, kind: 'year', items: [it] });\n      }\n    }\n  }\n  return groups.filter((g) => g.items.length || g.kind === 'section');\n}\n\n/** Последовательность строк с разрывами (в хронологическом/файловом порядке). */\nfunction withBreaks(groups, settings) {\n  let prev = null;\n  for (const g of groups) {\n    g.rows = [];\n    for (const it of g.items) {\n      const ev = it.ev;\n      const s = ev.dateSpec;\n      let gap = null;\n      if (prev && s && s.valid) gap = s.startIdx - prev.endIdx;\n      const auto = settings.autoBreakDays > 0 && gap != null && gap >= settings.autoBreakDays;\n      if (ev.breakText != null || auto) g.rows.push({ kind: 'break', gap, text: ev.breakText, explicit: ev.breakText != null, at: s && s.valid ? s.startIdx : null });\n      g.rows.push({ kind: 'event', ...it });\n      if (s && s.valid) prev = s;\n    }\n  }\n}\n\nfunction renderBreak(list, row) {\n  const el = list.createDiv({ cls: `tc-row tc-break${row.explicit ? '' : ' is-auto'}` });\n  const rail = el.createDiv({ cls: 'tc-rail' });\n  rail.createDiv({ cls: 'tc-break-dots' });\n  const pill = el.createDiv({ cls: 'tc-break-pill' });\n  setIcon(pill.createSpan({ cls: 'tc-break-pill-icon' }), 'history');\n  const parts = [];\n  const pause = row.gap != null && row.gap > 0 ? `пауза ${row.gap} ${plural(row.gap, ['день', 'дня', 'дней'])}` : '';\n  parts.push(row.explicit ? `Разрыв линии${pause ? ` (${pause})` : ''}` : pause.replace(/^п/, 'П'));\n  if (row.text) parts.push(row.text);\n  else if (row.explicit && row.at != null && row.gap > 27) parts.push(monthLabel(row.at - Math.floor(row.gap / 2)));\n  pill.createSpan({ text: parts.join(' — ') });\n}\n\n/**\n * @param parent  контейнер\n * @param card    модель карточки\n * @param ctx     { app, settings, sourcePath, component, block }\n */\nfunction renderList(parent, card, ctx) {\n  const { settings, block } = ctx;\n  const sortMode = block.ui.sortMode;\n  const query = block.ui.query.trim();\n  const total = card.entries.filter((e) => e.type === 'event').length;\n\n  const groups = buildGroups(card, settings, sortMode);\n  withBreaks(groups, settings);\n  if (sortMode === 'desc') {\n    groups.reverse();\n    groups.forEach((g) => g.rows.reverse());\n  }\n\n  const wrap = parent.createDiv({ cls: 'tc-feed' });\n  let shown = 0;\n  let firstHeader = true;\n\n  if (!total) {\n    const empty = wrap.createDiv({ cls: 'tc-empty' });\n    empty.createDiv({ text: 'Событий пока нет' });\n    const btn = empty.createEl('button', { cls: 'tc-btn tc-btn-primary', text: 'Добавить первое событие' });\n    btn.addEventListener('click', () => block.openForm());\n    return;\n  }\n\n  for (const g of groups) {\n    const visibleRows = g.rows.filter((r) => r.kind === 'event' ? matches(r.ev, query) : !query);\n    const count = visibleRows.filter((r) => r.kind === 'event').length;\n    if (query && !count) continue;\n    shown += count;\n\n    const header = wrap.createDiv({ cls: `tc-group-head is-${g.kind}` });\n    if (g.label) header.createDiv({ cls: 'tc-group-title', text: g.label });\n    header.createDiv({ cls: 'tc-chip tc-mono', text: `${count} ${plural(count, RECORDS)}` });\n    header.createDiv({ cls: 'tc-spacer' });\n    if (firstHeader) {\n      firstHeader = false;\n      const sortBtn = header.createDiv({ cls: 'tc-sort-btn' });\n      const labels = { file: 'Порядок как в заметке', asc: 'Хронологический порядок', desc: 'Сначала новые' };\n      const icons = { file: 'list', asc: 'arrow-down-wide-narrow', desc: 'arrow-up-wide-narrow' };\n      setIcon(sortBtn.createSpan({ cls: 'tc-sort-icon' }), icons[sortMode]);\n      sortBtn.createSpan({ text: labels[sortMode] });\n      sortBtn.setAttr('aria-label', 'Сменить порядок');\n      sortBtn.addEventListener('click', () => {\n        const order = ['file', 'asc', 'desc'];\n        block.setSort(order[(order.indexOf(sortMode) + 1) % order.length]);\n      });\n    }\n\n    const list = wrap.createDiv({ cls: 'tc-list' });\n    for (const row of visibleRows) {\n      if (row.kind === 'break') renderBreak(list, row);\n      else renderEventCard(list, row.ev, row.index, ctx);\n    }\n  }\n\n  const end = wrap.createDiv({ cls: 'tc-end' });\n  end.createSpan({ cls: 'tc-end-dot' });\n  end.createSpan({\n    text: query\n      ? `Найдено ${shown} из ${total} ${plural(total, ['события', 'событий', 'событий'])}`\n      : `Конец списка • ${total} ${plural(total, ['событие', 'события', 'событий'])}`,\n  });\n  if (query) {\n    const reset = end.createSpan({ cls: 'tc-end-reset', text: 'Сбросить поиск' });\n    reset.addEventListener('click', () => block.setQuery(''));\n  }\n}\n\nmodule.exports = { renderList, buildGroups, matches };\n","render/media":"'use strict';\n\n/*\n * Медиа события. Все встраивания файлов ![[файл.ext]] (не заметок) вынимаются\n * из текста и показываются отдельным блоком: плитки для фото/видео,\n * плеер для аудио, карточки-документы для PDF и прочего.\n * Картинки и видео рисуются напрямую через vault.getResourcePath() —\n * без асинхронного механизма эмбедов Obsidian (урок v2.2).\n */\n\nconst { setIcon, TFile } = require('obsidian');\nconst { IMAGE_EXT, VIDEO_EXT, AUDIO_EXT } = require('../constants');\nconst { formatSize, formatDuration } = require('../utils/text');\nconst { openLightbox } = require('../utils/dom');\n\nfunction kindOf(ext) {\n  const e = String(ext || '').toLowerCase();\n  if (IMAGE_EXT.includes(e)) return 'image';\n  if (VIDEO_EXT.includes(e)) return 'video';\n  if (AUDIO_EXT.includes(e)) return 'audio';\n  if (e === 'pdf') return 'pdf';\n  return 'file';\n}\n\n/** Вынимает медиа-встраивания из markdown. */\nfunction extractMedia(body, app, sourcePath) {\n  const items = [];\n  const text = String(body || '').replace(/!\\[\\[([^\\]\\n]+?)\\]\\]/g, (match, inner) => {\n    const [linkRaw, ...altParts] = inner.split('|');\n    const link = linkRaw.split('#')[0].trim();\n    const file = app.metadataCache.getFirstLinkpathDest(link, sourcePath);\n    if (!(file instanceof TFile) || file.extension === 'md' || file.extension === 'canvas') return match;\n    const alt = altParts.join('|').trim();\n    items.push({ file, link: linkRaw.trim(), alt: /^\\d+(x\\d+)?$/.test(alt) ? '' : alt, kind: kindOf(file.extension) });\n    return '';\n  });\n  // убираем строки, от которых остались только пробелы\n  const cleaned = text.split('\\n').filter((l, i, arr) => !(l.trim() === '' && (arr[i - 1] || '').trim() === '')).join('\\n').trim();\n  return { text: cleaned, items };\n}\n\n/** Медиа, подтянутое из связанной заметки, — пометка и подсказка. */\nfunction markLinked(tile, item) {\n  if (!item.from) return;\n  tile.addClass('is-linked');\n  tile.setAttr('aria-label', `Из заметки «${item.from}»`);\n  const chip = tile.createDiv({ cls: 'tc-media-from' });\n  setIcon(chip.createSpan(), 'link');\n  chip.createSpan({ text: item.from });\n}\n\nfunction caption(tile, item, settings, extra) {\n  if (!settings.showMediaCaptions) return;\n  const cap = tile.createDiv({ cls: 'tc-media-caption' });\n  cap.createSpan({ cls: 'tc-media-name', text: item.alt || item.file.name });\n  cap.createSpan({ cls: 'tc-media-size', text: extra || formatSize(item.file.stat.size) });\n}\n\nfunction renderImage(grid, item, ctx, gallery, index) {\n  const tile = grid.createDiv({ cls: 'tc-media-tile is-image' });\n  markLinked(tile, item);\n  const thumb = tile.createDiv({ cls: 'tc-media-thumb' });\n  const img = thumb.createEl('img', { attr: { src: ctx.app.vault.getResourcePath(item.file), alt: item.alt || item.file.name, loading: 'lazy' } });\n  img.addEventListener('error', () => { img.remove(); setIcon(thumb.createDiv({ cls: 'tc-media-placeholder' }), 'image-off'); });\n  thumb.addEventListener('click', (e) => {\n    e.stopPropagation();\n    if (e.ctrlKey || e.metaKey) ctx.app.workspace.openLinkText(item.file.path, ctx.sourcePath, true);\n    else openLightbox(gallery, index);\n  });\n  caption(tile, item, ctx.settings);\n}\n\nfunction renderVideo(grid, item, ctx) {\n  const tile = grid.createDiv({ cls: 'tc-media-tile is-video' });\n  markLinked(tile, item);\n  const thumb = tile.createDiv({ cls: 'tc-media-thumb' });\n  const video = thumb.createEl('video', { attr: { src: ctx.app.vault.getResourcePath(item.file), preload: 'metadata', playsinline: '' } });\n  const play = thumb.createDiv({ cls: 'tc-media-play' });\n  setIcon(play, 'play');\n  const badge = thumb.createDiv({ cls: 'tc-media-duration' });\n  video.addEventListener('loadedmetadata', () => {\n    if (isFinite(video.duration)) badge.setText(formatDuration(video.duration));\n  });\n  play.addEventListener('click', (e) => {\n    e.stopPropagation();\n    video.controls = true;\n    tile.addClass('is-playing');\n    video.play();\n  });\n  caption(tile, item, ctx.settings);\n}\n\nfunction renderAudio(list, item, ctx) {\n  const row = list.createDiv({ cls: 'tc-media-doc is-audio' });\n  const icon = row.createDiv({ cls: 'tc-media-doc-icon' });\n  setIcon(icon, 'music');\n  const info = row.createDiv({ cls: 'tc-media-doc-info' });\n  info.createDiv({ cls: 'tc-media-doc-name', text: item.alt || item.file.name });\n  info.createEl('audio', { attr: { src: ctx.app.vault.getResourcePath(item.file), controls: '', preload: 'none' } });\n}\n\nfunction renderDoc(list, item, ctx) {\n  const row = list.createDiv({ cls: `tc-media-doc is-${item.kind}` });\n  const icon = row.createDiv({ cls: 'tc-media-doc-icon' });\n  setIcon(icon, item.kind === 'pdf' ? 'file-text' : 'file');\n  const info = row.createDiv({ cls: 'tc-media-doc-info' });\n  info.createDiv({ cls: 'tc-media-doc-name', text: item.file.name });\n  const meta = [item.alt, item.file.extension.toUpperCase(), formatSize(item.file.stat.size)].filter(Boolean).join(' • ');\n  info.createDiv({ cls: 'tc-media-doc-meta', text: meta });\n  row.addEventListener('click', (e) => {\n    e.stopPropagation();\n    ctx.app.workspace.openLinkText(item.file.path, ctx.sourcePath, e.ctrlKey || e.metaKey || 'tab');\n  });\n}\n\nfunction renderMediaSection(parent, items, ctx) {\n  if (!items.length) return;\n  const section = parent.createDiv({ cls: 'tc-media' });\n  const visual = items.filter((i) => i.kind === 'image' || i.kind === 'video');\n  const docs = items.filter((i) => i.kind !== 'image' && i.kind !== 'video');\n\n\n\n  if (visual.length) {\n    const grid = section.createDiv({ cls: 'tc-media-grid' });\n    grid.style.setProperty('--tc-media-min', `${Math.max(60, ctx.settings.mediaSize || 140)}px`);\n    const gallery = visual.filter((i) => i.kind === 'image')\n      .map((i) => ({ src: ctx.app.vault.getResourcePath(i.file), alt: i.alt || i.file.name }));\n    let gi = 0;\n    for (const item of visual) {\n      if (item.kind === 'image') renderImage(grid, item, ctx, gallery, gi++);\n      else renderVideo(grid, item, ctx);\n    }\n  }\n  if (docs.length) {\n    const list = section.createDiv({ cls: 'tc-media-docs' });\n    for (const item of docs) {\n      if (item.kind === 'audio') renderAudio(list, item, ctx);\n      else renderDoc(list, item, ctx);\n    }\n  }\n}\n\nmodule.exports = { extractMedia, renderMediaSection, kindOf };\n","settings":"'use strict';\n\nconst { PluginSettingTab, Setting, Modal, MarkdownRenderer, Notice, normalizePath } = require('obsidian');\nconst { DEFAULT_SETTINGS, THEME_PRESETS } = require('./constants');\n\nconst LEGACY_PLUGIN_DIR = 'timeline-card';\n\n/** Загрузка настроек; при первом запуске подхватывает data.json старого Timeline Card. */\nasync function loadSettings(plugin) {\n  let data = await plugin.loadData();\n  if (!data) {\n    try {\n      const path = normalizePath(`${plugin.app.vault.configDir}/plugins/${LEGACY_PLUGIN_DIR}/data.json`);\n      if (await plugin.app.vault.adapter.exists(path)) {\n        const legacy = JSON.parse(await plugin.app.vault.adapter.read(path));\n        const keys = ['mediaSize', 'showMediaCaptions', 'autoDate', 'dateFormat', 'dateLocale', 'theme', 'customColor'];\n        data = {};\n        keys.forEach((k) => { if (legacy[k] !== undefined) data[k] = legacy[k]; });\n        if (data.theme === 'purple' && !legacy.customColor) delete data.theme;\n      }\n    } catch (e) { /* нет старых настроек — не страшно */ }\n  }\n  plugin.settings = Object.assign({}, DEFAULT_SETTINGS, data || {});\n  // 1.3.0 хранил короткий фрагмент для ката — теперь текст показывается целиком под «Показать полностью»\n  // 1.4: собственный текст события — как есть, текст из заметки — N строк + «Читать далее»\n  if ((plugin.settings.settingsVersion || 0) < 140) {\n    plugin.settings.collapseLongText = false;\n    plugin.settings.excerptLength = DEFAULT_SETTINGS.excerptLength;\n    plugin.settings.settingsVersion = 140;\n    if (data) await plugin.saveData(plugin.settings);\n  }\n  if (!THEME_PRESETS[plugin.settings.theme] && plugin.settings.theme !== 'custom') plugin.settings.theme = 'purple';\n}\n\nclass ReadmeModal extends Modal {\n  constructor(app, plugin, content) {\n    super(app);\n    this.plugin = plugin;\n    this.content = content;\n  }\n  async onOpen() {\n    this.modalEl.addClass('tc-readme-modal-wrap');\n    this.titleEl.setText('Event Timeline — README');\n    this.contentEl.addClass('tc-readme-modal', 'markdown-rendered');\n    if (MarkdownRenderer.render) await MarkdownRenderer.render(this.app, this.content, this.contentEl, '', this.plugin);\n    else await MarkdownRenderer.renderMarkdown(this.content, this.contentEl, '', this.plugin);\n  }\n  onClose() { this.contentEl.empty(); }\n}\n\nclass SettingsTab extends PluginSettingTab {\n  constructor(app, plugin) {\n    super(app, plugin);\n    this.plugin = plugin;\n  }\n\n  async save(refresh = true) {\n    await this.plugin.saveData(this.plugin.settings);\n    if (refresh) this.plugin.refreshAll();\n  }\n\n  num(setting, key, { min = 0, max = 100000, placeholder }) {\n    setting.addText((t) => {\n      t.inputEl.type = 'number';\n      t.setPlaceholder(placeholder || String(DEFAULT_SETTINGS[key]))\n        .setValue(String(this.plugin.settings[key]))\n        .onChange(async (v) => {\n          const n = parseInt(v, 10);\n          this.plugin.settings[key] = isNaN(n) ? DEFAULT_SETTINGS[key] : Math.max(min, Math.min(max, n));\n          await this.save();\n        });\n    });\n  }\n\n  toggle(setting, key) {\n    setting.addToggle((t) => t.setValue(!!this.plugin.settings[key]).onChange(async (v) => {\n      this.plugin.settings[key] = v;\n      await this.save();\n    }));\n  }\n\n  display() {\n    const { containerEl } = this;\n    const s = this.plugin.settings;\n    containerEl.empty();\n\n    new Setting(containerEl)\n      .setName('README')\n      .setDesc('Формат блока ```timeline, совместимость с ```track, все возможности.')\n      .addButton((b) => b.setButtonText('Открыть README').onClick(async () => {\n        try {\n          const content = await this.app.vault.adapter.read(normalizePath(`${this.plugin.manifest.dir}/README.md`));\n          new ReadmeModal(this.app, this.plugin, content).open();\n        } catch (e) {\n          new Notice(`Не удалось прочитать README.md: ${e.message}`);\n        }\n      }));\n\n    new Setting(containerEl).setName('Оформление').setHeading();\n    new Setting(containerEl)\n      .setName('Акцентный цвет')\n      .setDesc('Кнопки, ссылки, акцентный буллет. Для отдельного таймлайна цвет меняется кружком в его шапке.')\n      .addDropdown((dd) => {\n        Object.entries(THEME_PRESETS).forEach(([k, p]) => dd.addOption(k, p.label));\n        dd.addOption('custom', 'Свой…');\n        dd.setValue(s.theme).onChange(async (v) => { s.theme = v; await this.save(); this.display(); });\n      });\n    if (s.theme === 'custom') {\n      new Setting(containerEl).setName('Свой цвет').addColorPicker((cp) => cp.setValue(s.customColor).onChange(async (v) => {\n        s.customColor = v;\n        await this.save();\n      }));\n    }\n    this.num(new Setting(containerEl).setName('Максимальная ширина (px)').setDesc('Ширина таймлайна в заметке.'), 'maxWidth', { min: 420, max: 2000 });\n    this.toggle(new Setting(containerEl).setName('Показывать ID событий').setDesc('Строка «ID: #…» в углу карточки.'), 'showIds');\n    this.toggle(new Setting(containerEl).setName('Теги из связанных заметок').setDesc('Если в тексте события есть [[ссылка]] на заметку, её теги показываются на карточке (пунктирной рамкой) и участвуют в поиске.'), 'linkedTags');\n    this.toggle(new Setting(containerEl).setName('Медиа из связанных заметок').setDesc('Картинки и видео, встроенные в заметку по [[ссылке]] из события, показываются в медиа карточки.'), 'linkedMedia');\n    this.toggle(new Setting(containerEl).setName('Текст связанной заметки').setDesc('Если текст события — только [[ссылка]], под ней показывается текст этой заметки; длинный сворачивается под «Показать полностью».'), 'linkedExcerpt');\n    this.num(new Setting(containerEl).setName('Строк текста из заметки').setDesc('Сколько строк связанной заметки показывать в карточке; дальше — «Читать далее».'), 'excerptLines', { min: 1, max: 30 });\n    this.num(new Setting(containerEl).setName('Максимум текста заметки (символов)').setDesc('Сколько текста связанной заметки читать для карточки (обрезается по абзацам). На экране видно только заданное число строк.'), 'excerptLength', { min: 200, max: 50000 });\n    this.toggle(new Setting(containerEl).setName('Скобки [[ ]] у ссылок').setDesc('Показывать ссылки в тексте событий в стиле макета — со скобками и пунктиром. Выключено — ссылки выглядят как в обычной заметке.'), 'linkBrackets');\n    this.toggle(new Setting(containerEl).setName('Поиск по событиям').setDesc('Поле поиска в шапке таймлайна.'), 'showSearch');\n\n    new Setting(containerEl).setName('Лента').setHeading();\n    new Setting(containerEl)\n      .setName('Порядок по умолчанию')\n      .setDesc('Меняется и прямо в таймлайне — кнопкой справа от заголовка группы. Порядок в самой заметке не трогается.')\n      .addDropdown((dd) => dd\n        .addOption('file', 'Как в заметке')\n        .addOption('asc', 'Хронологический (старые сверху)')\n        .addOption('desc', 'Сначала новые')\n        .setValue(s.sortMode)\n        .onChange(async (v) => { s.sortMode = v; this.plugin.resetUiSort(); await this.save(); }));\n    this.toggle(new Setting(containerEl).setName('Группировать по годам').setDesc('Если в блоке нет секций ####. С секциями группами служат они.'), 'groupByYear');\n    this.toggle(new Setting(containerEl).setName('Человекочитаемые даты').setDesc('«2026-01-03» показывается как «3 января 2026». В заметке остаётся как было.'), 'humanDates');\n    this.num(new Setting(containerEl).setName('Авто-разрыв линии (дней)').setDesc('Показывать паузу, если между событиями прошло не меньше N дней. 0 — только явные break::.'), 'autoBreakDays', { min: 0, max: 36500 });\n\n    new Setting(containerEl).setName('Добавление событий').setHeading();\n    new Setting(containerEl)\n      .setName('Куда вставлять новое событие')\n      .addDropdown((dd) => dd\n        .addOption('date', 'По дате (после последнего более раннего)')\n        .addOption('end', 'В конец блока')\n        .setValue(s.insertMode)\n        .onChange(async (v) => { s.insertMode = v; await this.save(false); }));\n    this.toggle(new Setting(containerEl).setName('Автоматически подставлять дату').setDesc('Поле даты в форме сразу заполняется текущими датой и временем.'), 'autoDate');\n    new Setting(containerEl)\n      .setName('Формат даты')\n      .setDesc('Нотация moment.js: YYYY-MM-DD HH:mm, D MMMM YYYY и т. п.')\n      .addText((t) => t.setPlaceholder('YYYY-MM-DD HH:mm').setValue(s.dateFormat).onChange(async (v) => {\n        s.dateFormat = v.trim() || DEFAULT_SETTINGS.dateFormat;\n        await this.save(false);\n      }));\n    new Setting(containerEl)\n      .setName('Язык даты')\n      .setDesc('Код локали moment.js: ru, en, de…')\n      .addText((t) => t.setPlaceholder('ru').setValue(s.dateLocale).onChange(async (v) => {\n        s.dateLocale = v.trim() || 'ru';\n        await this.save(false);\n      }));\n    this.toggle(new Setting(containerEl).setName('Форма открыта по умолчанию').setDesc('Иначе форма свёрнута до клика по «+ Запись».'), 'formOpenByDefault');\n\n    new Setting(containerEl).setName('Текст и медиа').setHeading();\n    this.toggle(new Setting(containerEl).setName('Сворачивать длинный собственный текст события').setDesc('По умолчанию выключено — текст события показывается как есть. Включите, чтобы длинный текст обрезался с «Показать полностью».'), 'collapseLongText');\n    this.num(new Setting(containerEl).setName('Строк до сворачивания'), 'collapseMaxLines', { min: 1, max: 100 });\n    this.num(new Setting(containerEl).setName('Размер медиа-плитки (px)').setDesc('Ширина плитки фото и видео; высота — 3/4 от ширины.'), 'mediaSize', { min: 60, max: 600 });\n    this.toggle(new Setting(containerEl).setName('Подписи под медиа').setDesc('Имя файла и размер под плиткой.'), 'showMediaCaptions');\n  }\n}\n\nmodule.exports = { loadSettings, SettingsTab, ReadmeModal };\n","utils/dates":"'use strict';\n\n/*\n * Разбор и форматирование дат событий.\n * Понимает: 2026-01-03, 2026-01, 2026, 03.01.2026, 01.2026,\n * «3 января 2026», «январь 2026», «янв 2026», а также периоды:\n * 2026-01-03..2026-01-10, «3–10 января 2026», «март — май 2026».\n */\n\nconst MONTHS_GEN = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня',\n  'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];\nconst MONTHS_NOM = ['Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',\n  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'];\n\nconst MONTH_STEMS = [\n  ['янв', 1], ['фев', 2], ['мар', 3], ['апр', 4], ['май', 5], ['мая', 5], ['мае', 5],\n  ['июн', 6], ['июл', 7], ['авг', 8], ['сен', 9], ['окт', 10], ['ноя', 11], ['дек', 12],\n  ['jan', 1], ['feb', 2], ['mar', 3], ['apr', 4], ['may', 5], ['jun', 6], ['jul', 7],\n  ['aug', 8], ['sep', 9], ['oct', 10], ['nov', 11], ['dec', 12],\n];\n\nfunction monthFromName(name) {\n  const n = String(name || '').toLowerCase().replace(/\\.$/, '');\n  if (n.length < 3) return 0;\n  for (const [stem, num] of MONTH_STEMS) if (n.startsWith(stem)) return num;\n  return 0;\n}\n\nconst pad = (n) => String(n).padStart(2, '0');\n\nfunction daysInMonth(y, m) {\n  return new Date(Date.UTC(y, m, 0)).getUTCDate();\n}\n\nfunction valid(p) {\n  if (!p || !p.y || p.y < 1 || p.y > 9999) return false;\n  if (p.m && (p.m < 1 || p.m > 12)) return false;\n  if (p.d && (p.d < 1 || p.d > daysInMonth(p.y, p.m))) return false;\n  return true;\n}\n\n/** Одна точка: { y, m, d, h, min } (m/d могут быть 0 — точность месяц/год; h=null — без времени). */\nfunction parsePoint(text) {\n  let s = String(text || '').trim().replace(/\\s+/g, ' ');\n  let time = null;\n  const t = s.match(/^(.*?)(?:,|\\s|T)\\s*(\\d{1,2}):(\\d{2})(?::\\d{2})?$/);\n  if (t && +t[2] < 24 && +t[3] < 60) { s = t[1].trim(); time = { h: +t[2], min: +t[3] }; }\n  const p = parseDay(s.replace(/\\s*г(од)?\\.?$/i, ''));\n  if (!p) return null;\n  if (time && p.d) Object.assign(p, time);\n  else if (time) return null;\n  return p;\n}\n\nfunction parseDay(s) {\n  let r;\n  if ((r = s.match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})$/))) return { y: +r[1], m: +r[2], d: +r[3] };\n  if ((r = s.match(/^(\\d{4})-(\\d{1,2})$/))) return { y: +r[1], m: +r[2], d: 0 };\n  if ((r = s.match(/^(\\d{4})$/))) return { y: +r[1], m: 0, d: 0 };\n  if ((r = s.match(/^(\\d{1,2})[./](\\d{1,2})[./](\\d{4})$/))) return { y: +r[3], m: +r[2], d: +r[1] };\n  if ((r = s.match(/^(\\d{1,2})[./](\\d{4})$/))) return { y: +r[2], m: +r[1], d: 0 };\n  if ((r = s.match(/^(\\d{1,2}) ([a-zа-яё]+\\.?),? (\\d{4})$/i))) {\n    const m = monthFromName(r[2]);\n    if (m) return { y: +r[3], m, d: +r[1] };\n  }\n  if ((r = s.match(/^([a-zа-яё]+\\.?),? (\\d{4})$/i))) {\n    const m = monthFromName(r[1]);\n    if (m) return { y: +r[2], m, d: 0 };\n  }\n  return null;\n}\n\n/** Левая часть периода может быть неполной: «3», «3 января», «март». */\nfunction parseLeft(text, right) {\n  const s = String(text || '').trim();\n  const full = parsePoint(s);\n  if (full) return full;\n  let r;\n  if ((r = s.match(/^(\\d{1,2})$/)) && right.m) return { y: right.y, m: right.m, d: +r[1] };\n  if ((r = s.match(/^(\\d{1,2}) ([a-zа-яё]+\\.?)$/i))) {\n    const m = monthFromName(r[2]);\n    if (m) return { y: right.y, m, d: +r[1] };\n  }\n  if ((r = s.match(/^([a-zа-яё]+\\.?)$/i))) {\n    const m = monthFromName(r[1]);\n    if (m) return { y: right.y, m, d: 0 };\n  }\n  if ((r = s.match(/^(\\d{1,2})[./](\\d{1,2})$/))) return { y: right.y, m: +r[2], d: +r[1] };\n  return null;\n}\n\nconst RANGE_SPLIT = /\\s*(?:\\.\\.|—|–|\\s-\\s|\\s+по\\s+)\\s*/;\n\nfunction dayIndexStart(p) {\n  return Math.floor(Date.UTC(p.y, (p.m || 1) - 1, p.d || 1) / 86400000);\n}\nfunction dayIndexEnd(p) {\n  const m = p.m || 12;\n  const d = p.d || daysInMonth(p.y, m);\n  return Math.floor(Date.UTC(p.y, m - 1, d) / 86400000);\n}\n\nfunction isoPoint(p) {\n  if (p.d && p.h != null) return `${p.y}-${pad(p.m)}-${pad(p.d)} ${pad(p.h)}:${pad(p.min)}`;\n  if (p.d) return `${p.y}-${pad(p.m)}-${pad(p.d)}`;\n  if (p.m) return `${p.y}-${pad(p.m)}`;\n  return String(p.y);\n}\n\n\n/* ---------- приблизительные даты: «начало октября», «конец 2025», «осень 2024», «2 квартал» ---------- */\n\nconst PREFIX_RE = /^(?:(?:примерно|около|ориентировочно|приблизительно|ок\\.|где-то|в|во|на|с)\\s+|[~≈]\\s*)/;\nconst PART_RE = /^(начал|середин|кон[еця]|перв\\S*\\s+половин|втор\\S*\\s+половин)\\S*(?:\\s+(.*))?$/;\nconst SEASONS = [['зим', 'winter'], ['весн', 'spring'], ['лет', 'summer'], ['осен', 'autumn']];\nconst ROMAN = { i: 1, ii: 2, iii: 3, iv: 4 };\n\nfunction partKey(word) {\n  if (word.startsWith('начал')) return 'start';\n  if (word.startsWith('середин')) return 'mid';\n  if (word.startsWith('кон')) return 'end';\n  if (word.startsWith('перв')) return 'h1';\n  return 'h2';\n}\n\n/** Диапазон месяцев/дней для части периода. */\nfunction monthPart(m, part) {\n  return (y) => {\n    const last = daysInMonth(y, m);\n    const span = { start: [1, 10], mid: [11, 20], end: [21, last], h1: [1, 15], h2: [16, last] }[part] || [1, last];\n    return { start: { y, m, d: span[0] }, end: { y, m, d: span[1] } };\n  };\n}\nfunction yearPart(part) {\n  const months = { start: [1, 3], mid: [6, 7], end: [10, 12], h1: [1, 6], h2: [7, 12] }[part];\n  return (y) => ({ start: { y, m: months[0], d: 1 }, end: { y, m: months[1], d: daysInMonth(y, months[1]) } });\n}\nfunction monthsRange(m1, m2) {\n  return (y) => {\n    const y1 = m1 > m2 ? y - 1 : y; // зима: декабрь прошлого года — февраль\n    return { start: { y: y1, m: m1, d: 1 }, end: { y, m: m2, d: daysInMonth(y, m2) } };\n  };\n}\n\n/**\n * Разбор «человеческих» дат. Возвращает { build(year) -> {start, end}, year|null, approx }\n * или null. year = null — год не указан, его подставит parseDate по соседним событиям.\n */\nfunction parseFuzzy(text) {\n  let s = String(text || '').toLowerCase().replace(/ё/g, 'е').replace(/\\s+/g, ' ').trim();\n  let prev;\n  do { prev = s; s = s.replace(PREFIX_RE, ''); } while (s !== prev);\n  s = s.replace(/\\s*(?:г\\.?|год[ауе]?)$/, '').trim();\n\n  let year = null;\n  const ym = s.match(/^(.*?)[\\s,]*(\\d{4})$/);\n  if (ym) { year = +ym[2]; s = ym[1].trim(); }\n\n  let part = null;\n  const pm = s.match(PART_RE);\n  if (pm) { part = partKey(pm[1]); s = (pm[2] || '').trim(); }\n\n  let build = null;\n  let approx = !!part;\n  let r;\n  if (!s && part && year) build = yearPart(part);\n  else if (!s) return null;\n  else if (!part && (r = s.match(/^(\\d{1,2}) ([a-zа-я]+\\.?)$/)) && monthFromName(r[2])) {\n    const m = monthFromName(r[2]); const d = +r[1];\n    build = (y) => ({ start: { y, m, d }, end: null });\n  } else if (!part && (r = s.match(/^(\\d{1,2})[./](\\d{1,2})$/)) && +r[2] >= 1 && +r[2] <= 12) {\n    const m = +r[2]; const d = +r[1];\n    build = (y) => ({ start: { y, m, d }, end: null });\n  } else if (monthFromName(s) && /^[a-zа-я]+\\.?$/.test(s)) {\n    const m = monthFromName(s);\n    build = part ? monthPart(m, part) : (y) => ({ start: { y, m, d: 0 }, end: null });\n  } else if ((r = SEASONS.find(([stem]) => s.startsWith(stem))) && /^[а-я]+$/.test(s)) {\n    build = { winter: monthsRange(12, 2), spring: monthsRange(3, 5), summer: monthsRange(6, 8), autumn: monthsRange(9, 11) }[r[1]];\n    approx = true;\n  } else if ((r = s.match(/^(\\d|i{1,3}|iv)\\s*-?(?:й|ый)?\\s*кв\\S*$/) || s.match(/^q([1-4])$/))) {\n    const q = ROMAN[r[1]] || +r[1];\n    if (q < 1 || q > 4) return null;\n    build = monthsRange(q * 3 - 2, q * 3);\n    approx = true;\n  } else return null;\n\n  if (part && !approx) approx = true;\n  return { build, year, approx };\n}\n\nfunction yearOf(idx) {\n  return new Date(idx * 86400000).getUTCFullYear();\n}\n\n/** Год для даты без года — по соседним событиям (prev/next — разобранные даты). */\nfunction inferYear(fz, opts) {\n  const { prev, next } = opts || {};\n  if (prev && prev.valid) {\n    let y = yearOf(prev.endIdx);\n    const b = fz.build(y);\n    if (dayIndexEnd(b.end || b.start) < prev.startIdx - 60) y += 1;\n    return y;\n  }\n  if (next && next.valid) {\n    let y = yearOf(next.startIdx);\n    const b = fz.build(y);\n    if (dayIndexStart(b.start) > next.endIdx + 60) y -= 1;\n    return y;\n  }\n  return opts && opts.fallbackYear ? opts.fallbackYear : null;\n}\n\n/**\n * Разбирает строку даты/периода.\n * opts: { prev, next, fallbackYear } — соседние даты для подстановки года\n * в «начало октября», «12 октября» и т. п.\n * @returns {{raw, valid, approx, yearInferred, needsYear, start, end, iso, startIdx, endIdx, sortKey, year}}\n */\nfunction parseDate(raw, opts) {\n  const text = String(raw || '').trim();\n  const out = {\n    raw: text, valid: false, approx: false, yearInferred: false, needsYear: false,\n    start: null, end: null, iso: text, startIdx: null, endIdx: null, sortKey: null, year: null,\n  };\n  if (!text) return out;\n\n  let start = null;\n  let end = null;\n  const pieces = text.split(RANGE_SPLIT);\n  if (pieces.length === 2) {\n    end = parsePoint(pieces[1]);\n    if (end) start = parseLeft(pieces[0], end);\n    if (!start) { start = null; end = null; }\n  }\n  if (!start) {\n    // «3-10 января 2026» без пробелов вокруг дефиса\n    const m = text.match(/^(\\d{1,2})-(\\d{1,2}) (.+)$/);\n    if (m) {\n      end = parsePoint(`${m[2]} ${m[3]}`);\n      if (end) start = { y: end.y, m: end.m, d: +m[1] };\n    }\n  }\n  if (!start) {\n    start = parsePoint(text);\n    end = null;\n  }\n  if (!start) {\n    // «~ 2025-05», «примерно 3 января 2026» — точная дата с пометкой «≈»\n    const stripped = text.replace(/^(?:~|≈|примерно|около|ориентировочно|приблизительно|ок\\.)\\s*/i, '');\n    if (stripped !== text) {\n      const inner = parseDate(stripped, opts);\n      if (inner.valid && !inner.approx) return Object.assign(inner, { raw: text, roughly: true });\n    }\n    const fz = parseFuzzy(text);\n    if (!fz) return out;\n    let y = fz.year;\n    if (y == null) {\n      y = inferYear(fz, opts);\n      if (y == null) { out.needsYear = true; return out; }\n      out.yearInferred = true;\n    }\n    const b = fz.build(y);\n    start = b.start;\n    end = b.end;\n    out.approx = fz.approx;\n    out.fuzzyYear = y;\n  }\n  if (!start || !valid(start) || (end && !valid(end))) return out;\n  if (end && dayIndexStart(end) < dayIndexStart(start)) [start, end] = [end, start];\n\n  out.valid = true;\n  out.start = start;\n  out.end = end;\n  out.year = out.fuzzyYear || start.y;\n  delete out.fuzzyYear;\n  out.iso = end ? `${isoPoint(start)}..${isoPoint(end)}` : isoPoint(start);\n  out.startIdx = dayIndexStart(start);\n  out.endIdx = dayIndexEnd(end || start);\n  out.sortKey = out.startIdx * 1440 + (start.h != null ? start.h * 60 + start.min : 0);\n  return out;\n}\n\nfunction formatPoint(p, withYear = true) {\n  const y = withYear ? ` ${p.y}` : '';\n  const tm = p.h != null ? `, ${pad(p.h)}:${pad(p.min)}` : '';\n  if (p.d) return `${p.d} ${MONTHS_GEN[p.m - 1]}${y}${tm}`;\n  if (p.m) return `${MONTHS_NOM[p.m - 1]}${y}`;\n  return String(p.y);\n}\n\n/** Человекочитаемая дата: «3 января 2026», «3–10 января 2026», «Март — Май 2026». */\nfunction formatDate(spec) {\n  if (!spec || !spec.valid) return spec ? spec.raw : '';\n  if (spec.roughly) return `≈ ${formatDate({ ...spec, roughly: false })}`;\n  if (spec.approx) {\n    const label = spec.raw.charAt(0).toUpperCase() + spec.raw.slice(1);\n    return spec.yearInferred ? `${label} ${spec.year}` : label;\n  }\n  const { start: a, end: b } = spec;\n  if (!b) return formatPoint(a);\n  if (a.y === b.y) {\n    if (a.d && b.d && a.m === b.m && a.h == null && b.h == null) return `${a.d}–${b.d} ${MONTHS_GEN[a.m - 1]} ${a.y}`;\n    return `${formatPoint(a, false)} — ${formatPoint(b)}`;\n  }\n  return `${formatPoint(a)} — ${formatPoint(b)}`;\n}\n\n/** Короткая дата для правой панели: 03.01.2026 */\nfunction formatShort(idx) {\n  if (idx == null) return '—';\n  const d = new Date(idx * 86400000);\n  return `${pad(d.getUTCDate())}.${pad(d.getUTCMonth() + 1)}.${d.getUTCFullYear()}`;\n}\n\n/** Название месяца по индексу дня — для подписей разрывов. */\nfunction monthLabel(idx) {\n  const d = new Date(idx * 86400000);\n  return `${MONTHS_NOM[d.getUTCMonth()]} ${d.getUTCFullYear()}`;\n}\n\nfunction todayIso() {\n  const d = new Date();\n  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;\n}\n\nmodule.exports = { parseDate, parseFuzzy, formatDate, formatShort, monthLabel, todayIso, MONTHS_GEN, MONTHS_NOM };\n","utils/dom":"'use strict';\n\nconst { THEME_PRESETS, HOVER_SOURCE } = require('../constants');\n\nfunction autoResize(textarea) {\n  textarea.style.height = 'auto';\n  textarea.style.height = `${textarea.scrollHeight + 2}px`;\n}\n\n/** Акцентный цвет: значение из %% color %% (пресет или hex) или глобальная тема. */\nfunction resolveAccent(value, settings) {\n  const global = settings.theme === 'custom'\n    ? settings.customColor\n    : (THEME_PRESETS[settings.theme] || THEME_PRESETS.purple).color;\n  if (!value) return global;\n  if (value.startsWith('#')) return value;\n  const preset = THEME_PRESETS[value.toLowerCase()];\n  return preset ? preset.color : global;\n}\n\n/**\n * Наведение на ссылку -> нативное превью Page Preview. Источник HOVER_SOURCE\n * регистрируется в plugin.js с defaultMod: true — нужен Cmd/Ctrl,\n * а поведение можно поменять в настройках Page preview.\n */\nfunction wireHoverPreview(container, app, sourcePath, hoverParent) {\n  container.addEventListener('mouseover', (event) => {\n    const linkEl = event.target.closest && event.target.closest('a.internal-link, .tc-link');\n    if (!linkEl || !container.contains(linkEl)) return;\n    const linktext = linkEl.getAttribute('data-href') || linkEl.getAttribute('href') || '';\n    if (!linktext) return;\n    app.workspace.trigger('hover-link', {\n      event, source: HOVER_SOURCE, hoverParent: hoverParent || container, targetEl: linkEl, linktext, sourcePath,\n    });\n  });\n}\n\n/** Клик по внутренним ссылкам там, где Obsidian сам их не обрабатывает (боковая панель, граф). */\nfunction wireLinkClicks(container, app, sourcePath) {\n  container.addEventListener('click', (event) => {\n    const linkEl = event.target.closest && event.target.closest('a.internal-link, .tc-link');\n    if (!linkEl || !container.contains(linkEl)) return;\n    event.preventDefault();\n    const linktext = linkEl.getAttribute('data-href') || linkEl.getAttribute('href');\n    if (linktext) app.workspace.openLinkText(linktext, sourcePath, event.ctrlKey || event.metaKey);\n  });\n}\n\n/* ---------- Полноэкранный просмотр изображений с листанием ---------- */\nlet activeLightbox = null;\n\nfunction openLightbox(items, startIndex = 0) {\n  if (activeLightbox) activeLightbox.close();\n  let index = startIndex;\n  const overlay = document.body.createDiv({ cls: 'tc-lightbox' });\n  const img = overlay.createEl('img', { cls: 'tc-lightbox-img' });\n  const caption = overlay.createDiv({ cls: 'tc-lightbox-caption' });\n  const prev = items.length > 1 ? overlay.createDiv({ cls: 'tc-lightbox-nav is-prev', text: '‹' }) : null;\n  const next = items.length > 1 ? overlay.createDiv({ cls: 'tc-lightbox-nav is-next', text: '›' }) : null;\n\n  const show = () => {\n    const it = items[index];\n    img.src = it.src;\n    img.alt = it.alt || '';\n    caption.setText(items.length > 1 ? `${it.alt || ''}  ·  ${index + 1} / ${items.length}` : (it.alt || ''));\n  };\n  const step = (d) => { index = (index + d + items.length) % items.length; show(); };\n  const onKey = (e) => {\n    if (e.key === 'Escape') close();\n    else if (e.key === 'ArrowRight') step(1);\n    else if (e.key === 'ArrowLeft') step(-1);\n  };\n  const close = () => {\n    overlay.remove();\n    document.removeEventListener('keydown', onKey, true);\n    if (activeLightbox && activeLightbox.overlay === overlay) activeLightbox = null;\n  };\n  if (prev) prev.addEventListener('click', (e) => { e.stopPropagation(); step(-1); });\n  if (next) next.addEventListener('click', (e) => { e.stopPropagation(); step(1); });\n  img.addEventListener('click', (e) => { e.stopPropagation(); if (items.length > 1) step(1); else close(); });\n  overlay.addEventListener('click', close);\n  document.addEventListener('keydown', onKey, true);\n  show();\n  activeLightbox = { overlay, close };\n}\n\n/** Поповер, закрывающийся по клику мимо. */\nfunction openPopover(anchor, build, cls = '') {\n  document.querySelectorAll('.tc-popover').forEach((p) => p.remove());\n  const pop = document.body.createDiv({ cls: `tc-popover ${cls}` });\n  const close = () => {\n    pop.remove();\n    document.removeEventListener('mousedown', onDown, true);\n  };\n  const onDown = (e) => { if (!pop.contains(e.target) && !anchor.contains(e.target)) close(); };\n  build(pop, close);\n  const r = anchor.getBoundingClientRect();\n  const w = pop.offsetWidth || 220;\n  pop.style.top = `${r.bottom + 6}px`;\n  pop.style.left = `${Math.max(8, Math.min(window.innerWidth - w - 8, r.right - w))}px`;\n  setTimeout(() => document.addEventListener('mousedown', onDown, true), 0);\n  return close;\n}\n\nmodule.exports = { autoResize, resolveAccent, wireHoverPreview, wireLinkClicks, openLightbox, openPopover };\n","utils/text":"'use strict';\n\n/** Русское склонение: plural(5, ['запись', 'записи', 'записей']) */\nfunction plural(n, forms) {\n  const a = Math.abs(n) % 100;\n  const b = a % 10;\n  if (a > 10 && a < 20) return forms[2];\n  if (b > 1 && b < 5) return forms[1];\n  if (b === 1) return forms[0];\n  return forms[2];\n}\n\nfunction formatSize(bytes) {\n  if (bytes == null || isNaN(bytes)) return '';\n  const units = ['Б', 'КБ', 'МБ', 'ГБ'];\n  let v = bytes;\n  let i = 0;\n  while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }\n  const num = i === 0 || v >= 100 ? Math.round(v) : Math.round(v * 10) / 10;\n  return `${String(num).replace('.', ',')} ${units[i]}`;\n}\n\nfunction formatDuration(sec) {\n  if (!isFinite(sec)) return '';\n  sec = Math.round(sec);\n  const h = Math.floor(sec / 3600);\n  const m = Math.floor((sec % 3600) / 60);\n  const s = sec % 60;\n  const mm = h ? String(m).padStart(2, '0') : String(m);\n  return `${h ? h + ':' : ''}${mm}:${String(s).padStart(2, '0')}`;\n}\n\n/** Стабильный номер цвета (0..n-1) для тега. */\nfunction hashIndex(str, n) {\n  let h = 0;\n  for (const ch of String(str)) h = (h * 31 + ch.codePointAt(0)) >>> 0;\n  return h % n;\n}\n\nfunction debounce(fn, ms) {\n  let t = null;\n  const wrapped = (...args) => {\n    clearTimeout(t);\n    t = setTimeout(() => fn(...args), ms);\n  };\n  wrapped.cancel = () => clearTimeout(t);\n  return wrapped;\n}\n\n/** «#a, #b c» -> ['a', 'b', 'c'] */\nfunction parseTags(text) {\n  return String(text || '')\n    .split(/[\\s,;]+/)\n    .map((t) => t.replace(/^#+/, '').trim())\n    .filter(Boolean)\n    .filter((t, i, arr) => arr.indexOf(t) === i);\n}\n\nfunction slugify(text) {\n  return String(text || '')\n    .toLowerCase()\n    .replace(/[^\\p{L}\\p{N}]+/gu, '-')\n    .replace(/^-+|-+$/g, '')\n    .slice(0, 40);\n}\n\nmodule.exports = { plural, formatSize, formatDuration, hashIndex, debounce, parseTags, slugify };\n","view/PropertiesView":"'use strict';\n\n/*\n * Панель «Свойства таймлайна» в правом сайдбаре: период записей, стили буллетов,\n * связанные wiki-ссылки, статус и превью графа — для активной заметки.\n */\n\nconst { ItemView, TFile, setIcon } = require('obsidian');\nconst { PROPS_VIEW_TYPE, BLOCK_LANGUAGES, MARKERS, MARKER_ORDER } = require('../constants');\nconst { findTrackBlocks, parseCard } = require('../model/parser');\nconst { cardStats, buildGraph } = require('../model/stats');\nconst { annotateLinkedTags } = require('../model/linkedTags');\nconst { formatShort } = require('../utils/dates');\nconst { plural, debounce } = require('../utils/text');\nconst { renderGraph } = require('../render/graph');\nconst { wireHoverPreview } = require('../utils/dom');\n\nclass PropertiesView extends ItemView {\n  constructor(leaf, plugin) {\n    super(leaf);\n    this.plugin = plugin;\n    this.file = null;\n    this.refresh = debounce(() => this.update(), 250);\n  }\n\n  getViewType() { return PROPS_VIEW_TYPE; }\n  getDisplayText() { return 'Свойства таймлайна'; }\n  getIcon() { return 'calendar-range'; }\n\n  async onOpen() {\n    this.contentEl.addClass('tc-props');\n    wireHoverPreview(this.contentEl, this.app, '', this.contentEl);\n    this.registerEvent(this.app.workspace.on('active-leaf-change', () => this.refresh()));\n    this.registerEvent(this.app.workspace.on('file-open', () => this.refresh()));\n    this.registerEvent(this.app.vault.on('modify', (f) => { if (this.file && f.path === this.file.path) this.refresh(); }));\n    this.registerEvent(this.app.metadataCache.on('resolved', () => this.refresh()));\n    await this.update();\n  }\n\n  async onClose() {\n    this.refresh.cancel();\n  }\n\n  currentFile() {\n    const f = this.app.workspace.getActiveFile();\n    if (f instanceof TFile && f.extension === 'md') return f;\n    return this.file && this.app.vault.getAbstractFileByPath(this.file.path) ? this.file : null;\n  }\n\n  async update() {\n    const file = this.currentFile();\n    this.file = file;\n    const el = this.contentEl;\n    el.empty();\n    const head = el.createDiv({ cls: 'tc-props-head' });\n    head.createDiv({ cls: 'tc-props-title', text: 'Свойства заметки' });\n\n    if (!file) { el.createDiv({ cls: 'tc-props-empty', text: 'Откройте заметку с таймлайном' }); return; }\n    const content = await this.app.vault.cachedRead(file);\n    const blocks = findTrackBlocks(content, BLOCK_LANGUAGES);\n    if (!blocks.length) {\n      el.createDiv({ cls: 'tc-props-empty', text: 'В этой заметке нет блоков ```timeline' });\n      const btn = el.createEl('button', { cls: 'tc-btn', text: 'Вставить таймлайн' });\n      btn.addEventListener('click', () => this.plugin.insertTemplateIntoActive());\n      return;\n    }\n    const cards = blocks.map((b) => annotateLinkedTags(this.app, parseCard(b.source), file.path, { tags: this.plugin.settings.linkedTags, media: false }));\n    const st = cardStats(cards);\n\n    /* период */\n    const period = this.box(el, 'Период записей');\n    period.createDiv({ cls: 'tc-props-value', text: st.min != null ? `${formatShort(st.min)} — ${formatShort(st.max)}` : 'даты не распознаны' });\n    period.createDiv({ cls: 'tc-props-sub', text: `${st.total} ${plural(st.total, ['событие', 'события', 'событий'])}${cards.length > 1 ? ` в ${cards.length} блоках` : ''}` });\n\n    /* стили буллетов */\n    const legend = this.box(el, 'Стили буллетов');\n    for (const key of MARKER_ORDER) {\n      if (key === 'empty' && !st.counts.empty) continue;\n      const row = legend.createDiv({ cls: `tc-props-legend is-${key}` });\n      row.createSpan({ cls: 'tc-props-dot' });\n      row.createSpan({ cls: 'tc-props-legend-label', text: MARKERS[key].legend });\n      row.createSpan({ cls: 'tc-props-count', text: String(st.counts[key] || 0) });\n      row.addEventListener('click', () => this.plugin.focusQueryInActive(`marker:${key}`));\n    }\n\n    /* ссылки */\n    if (st.links.size) {\n      const links = this.box(el, 'Связанные wiki-ссылки');\n      const sorted = [...st.links.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));\n      for (const [target, n] of sorted.slice(0, 30)) {\n        const resolved = this.app.metadataCache.getFirstLinkpathDest(target, file.path);\n        const a = links.createEl('a', { cls: `tc-link tc-props-link${resolved ? '' : ' is-unresolved'}`, text: `[[${target}]]`, attr: { 'data-href': target } });\n        if (n > 1) a.createSpan({ cls: 'tc-props-count', text: ` ×${n}` });\n        a.addEventListener('click', (e) => { e.preventDefault(); this.app.workspace.openLinkText(target, file.path, e.ctrlKey || e.metaKey); });\n      }\n      if (sorted.length > 30) links.createDiv({ cls: 'tc-props-sub', text: `и ещё ${sorted.length - 30}` });\n    }\n\n    /* статус */\n    if (st.statuses.length) {\n      const status = this.box(el, 'Статус верификации');\n      for (const s of st.statuses) {\n        const row = status.createDiv({ cls: 'tc-props-status' });\n        row.createSpan({ cls: 'tc-props-dot is-done' });\n        row.createSpan({ text: s });\n      }\n    }\n\n    /* теги */\n    if (st.tags.length) {\n      const tags = this.box(el, 'Теги');\n      const wrap = tags.createDiv({ cls: 'tc-tags' });\n      st.tags.slice(0, 24).forEach((t) => {\n        const pill = wrap.createSpan({ cls: 'tc-tag', text: `#${t}` });\n        pill.addEventListener('click', () => this.plugin.focusQueryInActive(`#${t}`));\n      });\n    }\n\n    /* граф */\n    el.createDiv({ cls: 'tc-props-sep' });\n    const gbox = this.box(el, 'Граф связей (превью)', 'tc-props-graph');\n    const graph = buildGraph(cards);\n    renderGraph(gbox, graph, {\n      compact: true, width: 240, height: 140,\n      resolved: (l) => !!this.app.metadataCache.getFirstLinkpathDest(l, file.path),\n      onPage: (n, ev) => this.app.workspace.openLinkText(n.label, file.path, ev.ctrlKey || ev.metaKey),\n      onEvent: () => this.plugin.setModeInActive('graph'),\n    });\n    const foot = gbox.createDiv({ cls: 'tc-props-graph-foot' });\n    const open = foot.createSpan({ cls: 'tc-props-open', text: 'Открыть граф' });\n    setIcon(open.createSpan({ cls: 'tc-props-open-icon' }), 'maximize-2');\n    open.addEventListener('click', () => this.plugin.setModeInActive('graph'));\n    foot.createSpan({ text: `${graph.nodes.length} ${plural(graph.nodes.length, ['узел', 'узла', 'узлов'])}` });\n  }\n\n  box(parent, label, cls = '') {\n    const box = parent.createDiv({ cls: `tc-props-box ${cls}` });\n    box.createDiv({ cls: 'tc-props-label', text: label });\n    return box;\n  }\n}\n\nmodule.exports = { PropertiesView };\n"}; // @@BUNDLE@@
